    #[link(name = "kernel32")]
    extern "system" {
        fn CloseHandle(handle: Handle) -> Bool;
        fn CreateFileW(
            filename: *const u16,
            desired_access: Dword,
            share_mode: Dword,
            security_attributes: Lpvoid,
            creation_disposition: Dword,
            flags_and_attributes: Dword,
            template_file: Handle,
        ) -> Handle;
        fn CreateThread(
            attrs: Lpvoid,
            stack_size: usize,
            start: ThreadStart,
            param: Lpvoid,
            flags: Dword,
            thread_id: *mut Dword,
        ) -> Handle;
        fn DisableThreadLibraryCalls(module: Hmodule) -> Bool;
        fn FreeLibraryAndExitThread(module: Hmodule, exit_code: Dword) -> !;
        fn GetCurrentProcessId() -> Dword;
        fn GetModuleFileNameW(module: Hmodule, filename: *mut u16, size: Dword) -> Dword;
        fn GetModuleHandleExW(flags: Dword, module_name: *const u16, module: *mut Hmodule) -> Bool;
        fn GetModuleHandleW(module_name: *const u16) -> Hmodule;
        fn GetTickCount64() -> u64;
        fn VirtualQuery(
            address: *const c_void,
            buffer: *mut MemoryBasicInformation,
            length: usize,
        ) -> usize;
        fn WriteFile(
            file: Handle,
            buffer: *const c_void,
            bytes_to_write: Dword,
            bytes_written: *mut Dword,
            overlapped: Lpvoid,
        ) -> Bool;
    }

    pub unsafe fn dll_main(module: Hmodule, reason: Dword) -> Bool {
        if reason == DLL_PROCESS_ATTACH {
            unsafe {
                DLL_MODULE = module;
                DisableThreadLibraryCalls(module);
                spawn_attach_worker();
            }
        }
        1
    }

    pub fn trigger_attach_worker_from_hook() {
        unsafe {
            spawn_attach_worker();
        }
    }

    unsafe fn spawn_attach_worker() {
        if ATTACH_WORKER_RUNNING
            .compare_exchange(0, 1, Ordering::SeqCst, Ordering::SeqCst)
            .is_err()
        {
            return;
        }
        let handle = unsafe {
            CreateThread(
                ptr::null_mut(),
                0,
                Some(attach_worker),
                ptr::null_mut(),
                0,
                ptr::null_mut(),
            )
        };
        if handle.is_null() {
            ATTACH_WORKER_RUNNING.store(0, Ordering::SeqCst);
        } else {
            unsafe {
                CloseHandle(handle);
            }
        }
    }

    unsafe extern "system" fn attach_worker(_param: Lpvoid) -> Dword {
        let mut module = ptr::null_mut();
        let module_pinned = unsafe {
            GetModuleHandleExW(
                GET_MODULE_HANDLE_EX_FLAG_FROM_ADDRESS,
                attach_worker as *const () as *const u16,
                &mut module,
            ) != 0
        };
        write_attach_heartbeat();
        ATTACH_WORKER_RUNNING.store(0, Ordering::SeqCst);
        if module_pinned {
            unsafe {
                FreeLibraryAndExitThread(module, 0);
            }
        }
        0
    }

    fn write_attach_heartbeat() {
        reset_static_definition_caches();
        let Some(mut path) = module_path() else {
            return;
        };
        let control = if is_hoi4_process() {
            collector_control(&path)
        } else {
            None
        };
        let state = if is_hoi4_process() {
            Some(CollectorState::resolve(control.as_ref()))
        } else {
            None
        };
        let pid = unsafe { GetCurrentProcessId() };
        let sidecar_log = control
            .as_ref()
            .map(|control| control.sidecar_log)
            .unwrap_or(true);
        path.set_file_name("collector_attach.jsonl");
        let mut file = if sidecar_log {
            OpenOptions::new().create(true).append(true).open(path).ok()
        } else {
            None
        };
        let mut pipe = open_pipe(
            pid,
            control
                .as_ref()
                .and_then(|control| control.pipe_token.as_deref()),
        );
        if let Some(control) = control {
            let mut compact_perf_gate_trackers = CompactPerfGateTrackers::default();
            prewarm_compact_division_roots(
                state.as_ref(),
                &control,
                &mut compact_perf_gate_trackers.division_roots,
            );
            let worker_started = Instant::now();
            let deadline = worker_started + Duration::from_millis(control.duration_ms as u64);
            let mut session_sequence = 1u64;
            let mut last_scheduled_game_hour: Option<i32> = None;
            let mut previous_division_movement: BTreeMap<u32, DivisionMovementSample> =
                BTreeMap::new();
            let mut last_clock_emit_elapsed_ms: Option<u64> = None;
            let mut land_combat_tracker = LandCombatTracker::default();
            let mut army_order_tracker = ArmyOrderTracker::default();
            let mut last_army_order_sample_elapsed_ms: Option<u64> = None;
            let mut naval_combat_tracker = NavalCombatTracker::default();
            let mut naval_combat_member_tracker = NavalCombatMemberTracker::default();
            let mut air_wing_tracker = AirWingTracker::default();
            let mut last_air_wing_sample_elapsed_ms: Option<u64> = None;
            let mut ship_stats_tracker = ShipStatsTracker::default();
            let mut last_ship_stats_sample_elapsed_ms: Option<u64> = None;
            let mut oob_command_tracker = OobCommandTracker::default();
            let mut last_oob_command_sample_elapsed_ms: Option<u64> = None;
            let mut compact_country_tracker = CompactCountryFrameTracker::default();
            while Instant::now() <= deadline {
                let elapsed_wall_ms = duration_millis_u64(worker_started.elapsed());
                let clock_sample = clock_sample_from_state(state.as_ref());
                let capture_boundary = capture_boundary_for_frame(
                    clock_sample.as_ref(),
                    &control,
                    &mut last_scheduled_game_hour,
                );
                if control.stream_format == CollectorStreamFormat::Compact {
                    if capture_boundary == "scheduled_hour_snapshot" {
                        let (records, next_sequence) = build_compact_extraction_gate_records(
                            state.as_ref(),
                            &control,
                            session_sequence,
                            elapsed_wall_ms,
                            clock_sample.as_ref(),
                            &mut compact_perf_gate_trackers,
                        );
                        if !records.is_empty() {
                            write_sinks(file.as_mut(), pipe, &records);
                            session_sequence = next_sequence;
                        }
                    }
                    if control.sample_ms != 0 {
                        thread::sleep(Duration::from_millis(control.sample_ms as u64));
                    }
                    continue;
                }
                let emit_clock_delta = scheduled_domain_enabled(Some(&control), RAW_CLOCK_DOMAIN)
                    && (control.sample_ms != 0
                        || capture_boundary == "scheduled_hour_snapshot"
                        || last_clock_emit_elapsed_ms != Some(elapsed_wall_ms));
                if emit_clock_delta {
                    if let Some(line) = build_clock_raw_domain_delta_line(
                        pid,
                        state.as_ref(),
                        &control,
                        Some(session_sequence),
                        Some(elapsed_wall_ms),
                        capture_boundary,
                        clock_sample.as_ref(),
                    ) {
                        write_sinks(file.as_mut(), pipe, line.as_bytes());
                        session_sequence = session_sequence.saturating_add(1);
                        last_clock_emit_elapsed_ms = Some(elapsed_wall_ms);
                    }
                }
                if should_emit_root_frame(&control, capture_boundary) {
                    let line = build_frame_line(
                        pid,
                        state.as_ref(),
                        Some(&control),
                        Some(session_sequence),
                        Some(elapsed_wall_ms),
                        Some(capture_boundary),
                        clock_sample.as_ref(),
                        Some(&mut compact_country_tracker),
                    );
                    write_sinks(file.as_mut(), pipe, line.as_bytes());
                    session_sequence = session_sequence.saturating_add(1);
                }
                if scheduled_domain_enabled(Some(&control), RAW_DIVISIONS_DOMAIN) {
                    for line in build_division_raw_domain_delta_lines(
                        pid,
                        state.as_ref(),
                        &control,
                        &mut previous_division_movement,
                        session_sequence,
                        Some(elapsed_wall_ms),
                        capture_boundary,
                    ) {
                        write_sinks(file.as_mut(), pipe, line.as_bytes());
                        session_sequence = session_sequence.saturating_add(1);
                    }
                }
                if scheduled_domain_enabled(Some(&control), RAW_LAND_COMBATS_DOMAIN) {
                    for line in build_land_combat_raw_domain_delta_lines(
                        pid,
                        state.as_ref(),
                        &control,
                        &mut land_combat_tracker,
                        session_sequence,
                        Some(elapsed_wall_ms),
                        capture_boundary,
                    ) {
                        write_sinks(file.as_mut(), pipe, line.as_bytes());
                        session_sequence = session_sequence.saturating_add(1);
                    }
                }
                let sample_army_orders =
                    scheduled_domain_enabled(Some(&control), RAW_ARMY_ORDERS_DOMAIN)
                        && last_army_order_sample_elapsed_ms
                            .map(|last| {
                                elapsed_wall_ms.saturating_sub(last) >= ARMY_ORDER_SAMPLE_MIN_MS
                            })
                            .unwrap_or(true);
                if sample_army_orders {
                    for line in build_army_order_raw_domain_delta_lines(
                        pid,
                        state.as_ref(),
                        &control,
                        &mut army_order_tracker,
                        session_sequence,
                        Some(elapsed_wall_ms),
                        capture_boundary,
                    ) {
                        write_sinks(file.as_mut(), pipe, line.as_bytes());
                        session_sequence = session_sequence.saturating_add(1);
                    }
                    last_army_order_sample_elapsed_ms = Some(elapsed_wall_ms);
                }
                if scheduled_domain_enabled(Some(&control), RAW_NAVAL_COMBATS_DOMAIN)
                    || scheduled_domain_enabled(Some(&control), RAW_NAVAL_COMBAT_MEMBERS_DOMAIN)
                {
                    for line in build_naval_combat_raw_domain_delta_lines(
                        pid,
                        state.as_ref(),
                        &control,
                        &mut naval_combat_tracker,
                        &mut naval_combat_member_tracker,
                        session_sequence,
                        Some(elapsed_wall_ms),
                        capture_boundary,
                    ) {
                        write_sinks(file.as_mut(), pipe, line.as_bytes());
                        session_sequence = session_sequence.saturating_add(1);
                    }
                }
                let sample_air_wings =
                    scheduled_domain_enabled(Some(&control), RAW_AIR_WINGS_DOMAIN)
                        && last_air_wing_sample_elapsed_ms
                            .map(|last| {
                                elapsed_wall_ms.saturating_sub(last) >= AIR_WING_SAMPLE_MIN_MS
                            })
                            .unwrap_or(true);
                if sample_air_wings {
                    for line in build_air_wing_raw_domain_delta_lines(
                        pid,
                        state.as_ref(),
                        &control,
                        &mut air_wing_tracker,
                        session_sequence,
                        Some(elapsed_wall_ms),
                        capture_boundary,
                    ) {
                        write_sinks(file.as_mut(), pipe, line.as_bytes());
                        session_sequence = session_sequence.saturating_add(1);
                    }
                    last_air_wing_sample_elapsed_ms = Some(elapsed_wall_ms);
                }
                let sample_ship_stats = scheduled_domain_enabled(Some(&control), RAW_SHIPS_DOMAIN)
                    && last_ship_stats_sample_elapsed_ms
                        .map(|last| {
                            elapsed_wall_ms.saturating_sub(last) >= SHIP_STATS_SAMPLE_MIN_MS
                        })
                        .unwrap_or(true);
                if sample_ship_stats {
                    for line in build_ship_stats_raw_domain_delta_lines(
                        pid,
                        state.as_ref(),
                        &control,
                        &mut ship_stats_tracker,
                        session_sequence,
                        Some(elapsed_wall_ms),
                        capture_boundary,
                    ) {
                        write_sinks(file.as_mut(), pipe, line.as_bytes());
                        session_sequence = session_sequence.saturating_add(1);
                    }
                    last_ship_stats_sample_elapsed_ms = Some(elapsed_wall_ms);
                }
                let sample_oob_command =
                    scheduled_domain_enabled(Some(&control), RAW_OOB_COMMAND_DOMAIN)
                        && last_oob_command_sample_elapsed_ms
                            .map(|last| {
                                elapsed_wall_ms.saturating_sub(last) >= OOB_COMMAND_SAMPLE_MIN_MS
                            })
                            .unwrap_or(true);
                if sample_oob_command {
                    for line in build_oob_command_raw_domain_delta_lines(
                        pid,
                        state.as_ref(),
                        &control,
                        &mut oob_command_tracker,
                        session_sequence,
                        Some(elapsed_wall_ms),
                        capture_boundary,
                    ) {
                        write_sinks(file.as_mut(), pipe, line.as_bytes());
                        session_sequence = session_sequence.saturating_add(1);
                    }
                    last_oob_command_sample_elapsed_ms = Some(elapsed_wall_ms);
                }
                if control.sample_ms != 0 {
                    thread::sleep(Duration::from_millis(control.sample_ms as u64));
                }
            }
        } else {
            let line = build_frame_line(pid, state.as_ref(), None, None, None, None, None, None);
            write_sinks(file.as_mut(), pipe, line.as_bytes());
        }
        if let Some(handle) = pipe.take() {
            unsafe {
                CloseHandle(handle);
            }
        }
    }

    fn reset_static_definition_caches() {
        if let Some(cache) = IDEA_TOKEN_CACHE.get() {
            if let Ok(mut guard) = cache.lock() {
                guard.clear();
            }
        }
        if let Some(cache) = TECH_BASE_COST_CACHE.get() {
            if let Ok(mut guard) = cache.lock() {
                guard.clear();
            }
        }
        if let Some(cache) = IDEOLOGY_GROUP_TOKEN_CACHE.get() {
            if let Ok(mut guard) = cache.lock() {
                guard.clear();
            }
        }
        if let Some(cache) = POLITICS_CHARACTER_CACHE.get() {
            if let Ok(mut guard) = cache.lock() {
                guard.clear();
            }
        }
        if let Some(cache) = FOCUS_TOKEN_CACHE.get() {
            if let Ok(mut guard) = cache.lock() {
                guard.clear();
            }
        }
        if let Some(cache) = DECISION_TOKEN_CACHE.get() {
            if let Ok(mut guard) = cache.lock() {
                guard.clear();
            }
        }
    }

