    fn build_oob_command_raw_domain_delta_lines(
        pid: Dword,
        state: Option<&CollectorState>,
        control: &CollectorControl,
        tracker: &mut OobCommandTracker,
        first_session_sequence: u64,
        elapsed_wall_ms: Option<u64>,
        capture_boundary: &str,
    ) -> Vec<String> {
        let Some(state) = state else {
            return Vec::new();
        };
        let Some(clock) = clock_sample_from_state(Some(state)) else {
            return Vec::new();
        };
        let current_samples = match sample_oob_command(state, control) {
            Ok(samples) => samples,
            Err(gap_kind) => {
                let tick_ms = unsafe { GetTickCount64() };
                let sequence = FRAME_SEQUENCE.fetch_add(1, Ordering::Relaxed);
                return oob_command_gap_raw_domain_delta_frame_line(
                    pid,
                    sequence,
                    Some(first_session_sequence),
                    tick_ms,
                    control,
                    elapsed_wall_ms,
                    capture_boundary,
                    &clock,
                    gap_kind,
                )
                .into_iter()
                .collect();
            }
        };
        if current_samples.is_empty() && tracker.previous.is_empty() {
            return Vec::new();
        }
        let mut lines = Vec::new();
        let mut session_sequence = first_session_sequence;
        let mut current = BTreeMap::new();
        for sample in current_samples {
            let key = sample.oob_key.clone();
            let changed_fields = tracker
                .previous
                .get(&key)
                .and_then(|old| oob_command_changed_fields(old, &sample))
                .unwrap_or_else(oob_command_all_fields);
            if !changed_fields.is_empty() {
                push_oob_command_delta_frame(
                    &mut lines,
                    &mut session_sequence,
                    pid,
                    control,
                    elapsed_wall_ms,
                    capture_boundary,
                    &clock,
                    &sample,
                    "sample",
                    &changed_fields,
                );
            }
            current.insert(key, sample);
        }
        for (key, old) in &tracker.previous {
            if current.contains_key(key) {
                continue;
            }
            push_oob_command_delta_frame(
                &mut lines,
                &mut session_sequence,
                pid,
                control,
                elapsed_wall_ms,
                capture_boundary,
                &clock,
                old,
                "delete",
                &["oob_key"],
            );
        }
        tracker.previous = current;
        lines
    }

    fn push_oob_command_delta_frame(
        lines: &mut Vec<String>,
        session_sequence: &mut u64,
        pid: Dword,
        control: &CollectorControl,
        elapsed_wall_ms: Option<u64>,
        capture_boundary: &str,
        clock: &ClockSample,
        sample: &OobCommandSample,
        op: &str,
        changed_fields: &[&str],
    ) {
        let tick_ms = unsafe { GetTickCount64() };
        let sequence = FRAME_SEQUENCE.fetch_add(1, Ordering::Relaxed);
        if let Some(line) = oob_command_raw_domain_delta_frame_line(
            pid,
            sequence,
            Some(*session_sequence),
            tick_ms,
            control,
            elapsed_wall_ms,
            capture_boundary,
            clock,
            sample,
            op,
            changed_fields,
        ) {
            lines.push(line);
            *session_sequence = session_sequence.saturating_add(1);
        }
    }

    fn sample_oob_command(
        state: &CollectorState,
        control: &CollectorControl,
    ) -> Result<Vec<OobCommandSample>, &'static str> {
        if !(control.oob_command_bridge_valid
            && oob_command_bridge_well_formed(&control.oob_command_bridge))
        {
            return Err("bridge_invalid");
        }
        if control.oob_command_bridge.is_empty() {
            return Ok(Vec::new());
        }
        let module_base = state.base;
        let mut army_ptr_to_id: BTreeMap<usize, u32> = BTreeMap::new();
        let mut ag_ptr_to_id: BTreeMap<usize, u32> = BTreeMap::new();
        let mut fleet_ptr_to_id: BTreeMap<usize, u32> = BTreeMap::new();
        let mut invalid_command_rows = 0u32;
        let mut sampled_command_rows = 0u32;
        for entry in control.oob_command_bridge.iter().filter(|entry| {
            matches!(
                entry.kind,
                OobCommandKind::Army | OobCommandKind::ArmyGroup | OobCommandKind::Fleet
            )
        }) {
            if validate_oob_command_bridge_entry(module_base, entry) {
                match entry.kind {
                    OobCommandKind::Army => {
                        army_ptr_to_id.insert(entry.body_ptr, entry.object_id);
                    }
                    OobCommandKind::ArmyGroup => {
                        ag_ptr_to_id.insert(entry.body_ptr, entry.object_id);
                    }
                    OobCommandKind::Fleet => {
                        fleet_ptr_to_id.insert(entry.body_ptr, entry.object_id);
                    }
                    _ => {}
                }
                sampled_command_rows = sampled_command_rows.saturating_add(1);
            } else {
                invalid_command_rows = invalid_command_rows.saturating_add(1);
            }
        }

        let mut divisions_by_army: BTreeMap<u32, Vec<u32>> = BTreeMap::new();
        for entry in control
            .oob_command_bridge
            .iter()
            .filter(|entry| entry.kind == OobCommandKind::Division)
        {
            if !validate_oob_command_bridge_entry(module_base, entry) {
                continue;
            }
            let Some(parent_ptr) =
                read_u64(entry.body_ptr.saturating_add(DIVISION_OFF_ARMY_PARENT))
                    .map(|v| v as usize)
            else {
                continue;
            };
            if let Some(army_id) = army_ptr_to_id.get(&parent_ptr).copied() {
                divisions_by_army
                    .entry(army_id)
                    .or_default()
                    .push(entry.object_id);
            }
        }

        let mut armies_by_ag: BTreeMap<u32, Vec<u32>> = BTreeMap::new();
        let mut army_samples = Vec::new();
        for entry in control
            .oob_command_bridge
            .iter()
            .filter(|entry| entry.kind == OobCommandKind::Army)
        {
            match sample_army_oob_row(module_base, entry, &ag_ptr_to_id, &mut divisions_by_army) {
                Some(sample) => {
                    if sample.parent_status == Some("exact") {
                        if let (Some(ag_id), Some(army_id)) = (sample.army_group_id, sample.army_id)
                        {
                            armies_by_ag.entry(ag_id).or_default().push(army_id);
                        }
                    }
                    army_samples.push(sample);
                }
                None => invalid_command_rows = invalid_command_rows.saturating_add(1),
            }
        }
        let mut task_force_samples = Vec::new();
        let mut task_forces_by_fleet: BTreeMap<u32, Vec<u32>> = BTreeMap::new();
        for entry in control
            .oob_command_bridge
            .iter()
            .filter(|entry| entry.kind == OobCommandKind::TaskForce)
        {
            match sample_task_force_oob_row(module_base, entry, &fleet_ptr_to_id) {
                Some(sample) => {
                    sampled_command_rows = sampled_command_rows.saturating_add(1);
                    if sample.parent_status == Some("exact") {
                        if let (Some(fleet_id), Some(task_force_id)) =
                            (sample.fleet_id, sample.task_force_id)
                        {
                            task_forces_by_fleet
                                .entry(fleet_id)
                                .or_default()
                                .push(task_force_id);
                        }
                    }
                    task_force_samples.push(sample);
                }
                None => invalid_command_rows = invalid_command_rows.saturating_add(1),
            }
        }
        if sampled_command_rows == 0 && invalid_command_rows > 0 {
            return Err("bridge_entry_invalid");
        }

        let mut rows = Vec::new();
        for ag_id in ag_ptr_to_id.values() {
            let mut member_army_ids = armies_by_ag.remove(ag_id).unwrap_or_default();
            member_army_ids.sort_unstable();
            member_army_ids.dedup();
            let member_army_count = member_army_ids.len() as u32;
            let (member_army_ids, member_army_status) =
                if member_army_ids.len() > MAX_OOB_INLINE_IDS {
                    (None, "overflow")
                } else {
                    (Some(member_army_ids), "exact")
                };
            rows.push(OobCommandSample {
                oob_key: format!("oob_command:army_group:{ag_id}"),
                entity_kind: "army_group",
                army_id: None,
                army_group_id: Some(*ag_id),
                fleet_id: None,
                task_force_id: None,
                member_division_ids: None,
                member_division_count: None,
                member_division_status: None,
                member_army_ids,
                member_army_count: Some(member_army_count),
                member_army_status: Some(member_army_status),
                leader_id: None,
                leader_status: None,
                leader_skill: None,
                leader_traits: None,
                leader_trait_status: None,
                member_count_engine: None,
                missing_member_count: None,
                task_force_ids: None,
                task_force_count: None,
                task_force_status: None,
                parent_status: None,
                ship_ids: None,
                ship_count: None,
                ship_status: None,
            });
        }
        rows.extend(army_samples);
        for fleet_id in fleet_ptr_to_id.values() {
            let mut task_force_ids = task_forces_by_fleet.remove(fleet_id).unwrap_or_default();
            task_force_ids.sort_unstable();
            task_force_ids.dedup();
            let task_force_count = task_force_ids.len() as u32;
            let (task_force_ids, task_force_status) = if task_force_ids.len() > MAX_OOB_INLINE_IDS {
                (None, "overflow")
            } else {
                (Some(task_force_ids), "exact")
            };
            rows.push(OobCommandSample {
                oob_key: format!("oob_command:fleet:{fleet_id}"),
                entity_kind: "fleet",
                army_id: None,
                army_group_id: None,
                fleet_id: Some(*fleet_id),
                task_force_id: None,
                member_division_ids: None,
                member_division_count: None,
                member_division_status: None,
                member_army_ids: None,
                member_army_count: None,
                member_army_status: None,
                leader_id: None,
                leader_status: None,
                leader_skill: None,
                leader_traits: None,
                leader_trait_status: None,
                member_count_engine: None,
                missing_member_count: None,
                task_force_ids,
                task_force_count: Some(task_force_count),
                task_force_status: Some(task_force_status),
                parent_status: None,
                ship_ids: None,
                ship_count: None,
                ship_status: None,
            });
        }
        rows.extend(task_force_samples);
        rows.sort_by(|a, b| a.oob_key.cmp(&b.oob_key));
        Ok(rows)
    }

    fn validate_oob_command_bridge_entry(
        module_base: usize,
        entry: &OobCommandBridgeEntry,
    ) -> bool {
        let Some((vtable_rva, type_tag)) = oob_command_kind_layout(entry.kind) else {
            return false;
        };
        if !is_map_control_heap_pointer(entry.body_ptr) {
            return false;
        }
        let Some(vtable) = module_base.checked_add(vtable_rva) else {
            return false;
        };
        if read_u64(entry.body_ptr).map(|v| v as usize) != Some(vtable) {
            return false;
        }
        let Some(handle_addr) = entry.body_ptr.checked_add(0x08) else {
            return false;
        };
        let Some(handle) = read_u64(handle_addr) else {
            return false;
        };
        (handle & 0xFFFF_FFFF) as u32 == type_tag
            && ((handle >> 32) & 0xFFFF_FFFF) as u32 == entry.object_id
    }

    fn oob_command_kind_layout(kind: OobCommandKind) -> Option<(usize, u32)> {
        match kind {
            OobCommandKind::Army => Some((ARMY_VTABLE_RVA, ARMY_TYPE)),
            OobCommandKind::ArmyGroup => Some((AG_VTABLE_RVA, ARMY_TYPE)),
            OobCommandKind::Fleet => Some((FLEET_VTABLE_RVA, OOB_TYPE_FLEET)),
            OobCommandKind::TaskForce => Some((TASK_FORCE_VTABLE_RVA, OOB_TYPE_FLEET)),
            OobCommandKind::Theatre => Some((THEATRE_VTABLE_RVA, OOB_TYPE_THEATRE)),
            OobCommandKind::Division => Some((DIVISION_VTABLE_RVA, DIVISION_TYPE)),
            OobCommandKind::Ship => Some((CSHIP_VTABLE_RVA, CSHIP_TYPE)),
        }
    }

    fn sample_army_oob_row(
        module_base: usize,
        entry: &OobCommandBridgeEntry,
        ag_ptr_to_id: &BTreeMap<usize, u32>,
        divisions_by_army: &mut BTreeMap<u32, Vec<u32>>,
    ) -> Option<OobCommandSample> {
        if entry.kind != OobCommandKind::Army
            || !validate_oob_command_bridge_entry(module_base, entry)
        {
            return None;
        }
        let parent_ptr = read_u64(entry.body_ptr.saturating_add(ARMY_OFF_AG_PARENT))
            .map(|v| v as usize)
            .unwrap_or(0);
        let army_group_id = ag_ptr_to_id.get(&parent_ptr).copied();
        let parent_status = if army_group_id.is_some() {
            "exact"
        } else {
            "unknown"
        };
        let mut member_division_ids = divisions_by_army
            .remove(&entry.object_id)
            .unwrap_or_default();
        member_division_ids.sort_unstable();
        member_division_ids.dedup();
        let live_member_count = member_division_ids.len() as u32;
        let member_count_engine = read_u32(entry.body_ptr.saturating_add(ARMY_OFF_MEMBER_COUNT));
        let missing_member_count =
            member_count_engine.and_then(|engine| engine.checked_sub(live_member_count));
        let (member_division_ids, member_division_status) =
            if member_division_ids.len() > MAX_OOB_INLINE_IDS {
                (None, "overflow")
            } else {
                (Some(member_division_ids), "exact")
            };
        let (leader_id, leader_status, leader_skill, leader_traits, leader_trait_status) =
            read_army_oob_leader_detail(module_base, entry.body_ptr);
        Some(OobCommandSample {
            oob_key: format!("oob_command:army:{}", entry.object_id),
            entity_kind: "army",
            army_id: Some(entry.object_id),
            army_group_id,
            fleet_id: None,
            task_force_id: None,
            member_division_ids,
            member_division_count: Some(live_member_count),
            member_division_status: Some(member_division_status),
            member_army_ids: None,
            member_army_count: None,
            member_army_status: None,
            leader_id,
            leader_status: Some(leader_status),
            leader_skill,
            leader_traits,
            leader_trait_status,
            member_count_engine,
            missing_member_count,
            task_force_ids: None,
            task_force_count: None,
            task_force_status: None,
            parent_status: Some(parent_status),
            ship_ids: None,
            ship_count: None,
            ship_status: None,
        })
    }

    fn read_army_oob_leader_detail(
        module_base: usize,
        army_body: usize,
    ) -> (
        Option<u32>,
        &'static str,
        Option<u32>,
        Option<Vec<String>>,
        Option<&'static str>,
    ) {
        let Some(leader_ptr) =
            read_u64(army_body.saturating_add(ARMY_OFF_LEADER_PTR)).map(|v| v as usize)
        else {
            return (None, "validation_failed", None, None, None);
        };
        if !is_map_control_heap_pointer(leader_ptr) {
            return (None, "unknown", None, None, None);
        }
        let Some(vtable) = read_u64(leader_ptr).map(|v| v as usize) else {
            return (None, "validation_failed", None, None, None);
        };
        let army_leader_vtable = module_base.saturating_add(ARMY_LEADER_VTABLE_RVA);
        let navy_leader_vtable = module_base.saturating_add(NAVY_LEADER_VTABLE_RVA);
        if vtable != army_leader_vtable && vtable != navy_leader_vtable {
            return (None, "validation_failed", None, None, None);
        }
        let Some(handle_type) = read_u32(leader_ptr.saturating_add(0x08)) else {
            return (None, "validation_failed", None, None, None);
        };
        if handle_type != DIVISION_TYPE {
            return (None, "validation_failed", None, None, None);
        }
        let Some(leader_id) = read_u32(leader_ptr.saturating_add(LEADER_OFF_ID)) else {
            return (None, "validation_failed", None, None, None);
        };
        if leader_id == 0 || leader_id > MAX_OOB_COMMAND_ID {
            (None, "validation_failed", None, None, None)
        } else {
            let leader_skill = read_unit_leader_skill(leader_ptr);
            let (leader_traits, leader_trait_status) =
                read_unit_leader_traits(module_base, leader_ptr);
            (
                Some(leader_id),
                "exact",
                leader_skill,
                leader_traits,
                Some(leader_trait_status),
            )
        }
    }

    fn read_unit_leader_skill(leader_ptr: usize) -> Option<u32> {
        let subobj = read_u64(leader_ptr.checked_add(UNIT_LEADER_SKILL_SUBOBJ_PTR)?)? as usize;
        if !is_map_control_heap_pointer(subobj) {
            return None;
        }
        let skill = read_u32(subobj.checked_add(UNIT_LEADER_SKILL_IN_SUBOBJ)?)?;
        (skill <= MAX_UNIT_LEADER_SKILL).then_some(skill)
    }

    fn read_unit_leader_traits(
        module_base: usize,
        leader_ptr: usize,
    ) -> (Option<Vec<String>>, &'static str) {
        let Some(data) =
            read_u64(leader_ptr.saturating_add(UNIT_LEADER_TRAIT_DATA)).map(|v| v as usize)
        else {
            return (None, "validation_failed");
        };
        let Some(capacity) = read_u32(leader_ptr.saturating_add(UNIT_LEADER_TRAIT_CAP)) else {
            return (None, "validation_failed");
        };
        let Some(size) = read_u32(leader_ptr.saturating_add(UNIT_LEADER_TRAIT_SIZE)) else {
            return (None, "validation_failed");
        };
        if size == 0 {
            return (Some(Vec::new()), "exact");
        }
        if size > capacity || size > MAX_UNIT_LEADER_TRAITS || !is_map_control_heap_pointer(data) {
            return (None, "validation_failed");
        }
        let mut traits = Vec::new();
        let trait_vtable = module_base.saturating_add(UNIT_LEADER_TRAIT_VTABLE_RVA) as u64;
        for index in 0..size {
            let Some(offset) = (index as usize).checked_mul(8) else {
                return (None, "validation_failed");
            };
            let Some(def_ptr) = data
                .checked_add(offset)
                .and_then(read_u64)
                .map(|v| v as usize)
            else {
                return (None, "validation_failed");
            };
            if !is_map_control_heap_pointer(def_ptr) || read_u64(def_ptr) != Some(trait_vtable) {
                return (None, "validation_failed");
            }
            let Some(token) = read_msvc_string(
                def_ptr.saturating_add(UNIT_LEADER_TRAIT_TOKEN),
                MAX_POLITICS_TOKEN_LEN,
            )
            .filter(|value| is_script_token(value)) else {
                return (None, "validation_failed");
            };
            traits.push(token);
        }
        (Some(traits), "exact")
    }

    fn sample_task_force_oob_row(
        module_base: usize,
        entry: &OobCommandBridgeEntry,
        fleet_ptr_to_id: &BTreeMap<usize, u32>,
    ) -> Option<OobCommandSample> {
        if entry.kind != OobCommandKind::TaskForce
            || !validate_oob_command_bridge_entry(module_base, entry)
        {
            return None;
        }
        let parent_ptr =
            read_u64(entry.body_ptr.checked_add(TASK_FORCE_OFF_FLEET_PARENT)?)? as usize;
        let fleet_id = fleet_ptr_to_id.get(&parent_ptr).copied();
        let parent_status = if fleet_id.is_some() {
            "exact"
        } else {
            "unknown"
        };
        let (ship_ids, ship_count, ship_status) =
            read_task_force_ship_ids(module_base, entry.body_ptr);
        Some(OobCommandSample {
            oob_key: format!("oob_command:task_force:{}", entry.object_id),
            entity_kind: "task_force",
            army_id: None,
            army_group_id: None,
            fleet_id,
            task_force_id: Some(entry.object_id),
            member_division_ids: None,
            member_division_count: None,
            member_division_status: None,
            member_army_ids: None,
            member_army_count: None,
            member_army_status: None,
            leader_id: None,
            leader_status: None,
            leader_skill: None,
            leader_traits: None,
            leader_trait_status: None,
            member_count_engine: None,
            missing_member_count: None,
            task_force_ids: None,
            task_force_count: None,
            task_force_status: None,
            parent_status: Some(parent_status),
            ship_ids,
            ship_count,
            ship_status: Some(ship_status),
        })
    }

    fn read_task_force_ship_ids(
        module_base: usize,
        task_force_body: usize,
    ) -> (Option<Vec<u32>>, Option<u32>, &'static str) {
        let Some(count) = read_u32(task_force_body.saturating_add(TASK_FORCE_OFF_SHIP_COUNT))
        else {
            return (None, None, "validation_failed");
        };
        if count == 0 {
            return (Some(Vec::new()), Some(0), "exact");
        }
        if count > MAX_OOB_TASK_FORCE_SHIPS {
            return (None, None, "validation_failed");
        }
        if count as usize > MAX_OOB_INLINE_IDS {
            return (None, Some(count), "overflow");
        }
        let Some(begin) =
            read_u64(task_force_body.saturating_add(TASK_FORCE_OFF_SHIP_BEGIN)).map(|v| v as usize)
        else {
            return (None, Some(count), "validation_failed");
        };
        if !is_map_control_heap_pointer(begin) {
            return (None, Some(count), "validation_failed");
        }
        let Some(byte_len) = (count as usize).checked_mul(8) else {
            return (None, Some(count), "validation_failed");
        };
        let Some(raw) = read_bytes(begin, byte_len) else {
            return (None, Some(count), "validation_failed");
        };
        if raw.len() < byte_len {
            return (None, Some(count), "validation_failed");
        }
        let mut ship_ids = Vec::new();
        let mut seen = BTreeMap::new();
        for index in 0..count as usize {
            let offset = index * 8;
            let ship_ptr = u64::from_le_bytes([
                raw[offset],
                raw[offset + 1],
                raw[offset + 2],
                raw[offset + 3],
                raw[offset + 4],
                raw[offset + 5],
                raw[offset + 6],
                raw[offset + 7],
            ]) as usize;
            let Some(instance_id) = read_cship_instance_id(module_base, ship_ptr) else {
                return (None, Some(count), "validation_failed");
            };
            if seen.insert(instance_id, ()).is_some() {
                return (None, Some(count), "validation_failed");
            }
            ship_ids.push(instance_id);
        }
        ship_ids.sort_unstable();
        (Some(ship_ids), Some(count), "exact")
    }

    fn read_cship_instance_id(module_base: usize, ship_ptr: usize) -> Option<u32> {
        if !is_map_control_heap_pointer(ship_ptr)
            || read_u64(ship_ptr)? as usize != module_base.checked_add(CSHIP_VTABLE_RVA)?
        {
            return None;
        }
        let handle = read_u64(ship_ptr.checked_add(CSHIP_OFF_HANDLE)?)?;
        if (handle & 0xFFFF_FFFF) as u32 != CSHIP_TYPE {
            return None;
        }
        let instance_id = ((handle >> 32) & 0xFFFF_FFFF) as u32;
        if instance_id == 0 || instance_id > MAX_SHIP_INSTANCE_ID {
            return None;
        }
        let ref100 = read_u32(ship_ptr.checked_add(CSHIP_OFF_REF100)?)?;
        (ref100 == CSHIP_REF100_RAW).then_some(instance_id)
    }

