    fn capture_boundary_for_frame(
        clock_sample: Option<&ClockSample>,
        control: &CollectorControl,
        last_scheduled_game_hour: &mut Option<i32>,
    ) -> &'static str {
        let Some(current_raw) = clock_sample.map(|sample| sample.raw_date) else {
            return "worker_poll";
        };
        let step = control.scheduled_snapshot_step_hours.max(1) as i32;
        let should_schedule = match *last_scheduled_game_hour {
            None => true,
            Some(previous_raw) => {
                current_raw != previous_raw && current_raw.saturating_sub(previous_raw) >= step
            }
        };
        if should_schedule {
            *last_scheduled_game_hour = Some(current_raw);
            "scheduled_hour_snapshot"
        } else {
            "worker_poll"
        }
    }

    fn should_emit_root_frame(control: &CollectorControl, capture_boundary: &str) -> bool {
        capture_boundary == "scheduled_hour_snapshot" || control.scheduled_domains.is_empty()
    }

    fn current_game_date_raw(state: Option<&CollectorState>) -> Option<i32> {
        let state = state?;
        if !(state.daily_match && state.long_string_match) {
            return None;
        }
        read_i32(state.date_ptr as usize + GS_CURRENT_DATE_OFFSET)
    }

    fn duration_millis_u64(duration: Duration) -> u64 {
        duration.as_millis().min(u128::from(u64::MAX)) as u64
    }

    fn duration_micros_u64(duration: Duration) -> u64 {
        duration.as_micros().min(u128::from(u64::MAX)) as u64
    }

    fn build_compact_extraction_gate_records(
        state: Option<&CollectorState>,
        control: &CollectorControl,
        sequence_start: u64,
        elapsed_wall_ms: u64,
        clock: Option<&ClockSample>,
        trackers: &mut CompactPerfGateTrackers,
    ) -> (Vec<u8>, u64) {
        let frame_started = Instant::now();
        let mut out = Vec::new();
        let mut sequence = sequence_start;
        let mut emitted_domains = 0u32;
        let mut status_flags = if control.extraction_perf_gate {
            COMPACT_STATUS_EXTRACTION_PERF_GATE
        } else {
            0
        };
        let game_hour_raw = clock.map(|sample| sample.raw_date).unwrap_or_else(|| {
            status_flags |= COMPACT_STATUS_NO_CLOCK;
            0
        });
        let Some(state) = state else {
            status_flags |= COMPACT_STATUS_STATE_UNAVAILABLE;
            append_compact_frame_end_record(
                &mut out,
                sequence,
                game_hour_raw,
                elapsed_wall_ms,
                duration_micros_u64(frame_started.elapsed()),
                emitted_domains,
                control.scheduled_domains.len().min(u32::MAX as usize) as u32,
                status_flags,
            );
            return (out, sequence.saturating_add(1));
        };
        if !(state.daily_match && state.long_string_match) {
            status_flags |= COMPACT_STATUS_PROFILE_MISMATCH;
        }
        if !state.country_identity.has_scalar_source() {
            status_flags |= COMPACT_STATUS_NO_SCALAR_SOURCE;
        }
        let enabled_specs = compact_country_domain_specs()
            .into_iter()
            .filter(|spec| scheduled_domain_enabled(Some(control), spec.name))
            .collect::<Vec<_>>();
        let divisions_enabled = compact_explicit_domain_enabled(control, RAW_DIVISIONS_DOMAIN);
        let division_equipment_enabled =
            compact_explicit_domain_enabled(control, RAW_DIVISION_EQUIPMENT_DOMAIN);
        let army_orders_enabled = compact_explicit_domain_enabled(control, RAW_ARMY_ORDERS_DOMAIN);
        let land_combats_enabled =
            compact_explicit_domain_enabled(control, RAW_LAND_COMBATS_DOMAIN);
        let map_control_enabled = compact_map_control_enabled(control);
        let map_detail_enabled = compact_map_detail_enabled(control);
        let weather_enabled = compact_weather_enabled(control);
        let map_detail_include_resources = compact_map_detail_include_resources(control);
        let map_detail_include_buildings = compact_map_detail_include_buildings(control);
        let mut country_reads = Vec::new();
        let mut division_read = None;
        let mut division_equipment_read = None;
        let mut army_order_read = None;
        let mut land_combat_read = None;
        let mut map_control_read = None;
        let mut map_detail_read = None;
        let mut weather_read = None;
        let country_specs_for_panic = enabled_specs.clone();
        if compact_division_roots_enabled(control) && !compact_division_bridge_available(control) {
            trackers.division_roots = discover_compact_division_roots(Some(state));
        }
        let country_trackers = CompactCountryGateTrackers {
            fuel: &mut trackers.fuel,
            production: &mut trackers.production,
            focus_tech: &mut trackers.focus_tech,
            politics: &mut trackers.politics,
            politics_residuals: &mut trackers.politics_residuals,
            decisions: &mut trackers.decisions,
            diplomacy: &mut trackers.diplomacy,
            combined: &mut trackers.combined,
        };
        let division_tracker = &mut trackers.division_movement;
        let division_equipment_tracker = &mut trackers.division_equipment;
        let army_order_tracker = &mut trackers.army_order;
        let division_roots = &trackers.division_roots;
        let land_combat_tracker = &mut trackers.land_combat;
        let map_control_tracker = &mut trackers.map_control;
        let map_detail_tracker = &mut trackers.map_detail;
        let weather_tracker = &mut trackers.weather;
        thread::scope(|scope| {
            let country_handle = if enabled_specs.is_empty() {
                None
            } else {
                Some(scope.spawn(move || {
                    read_compact_country_domain_bundles(
                        state,
                        control,
                        enabled_specs,
                        status_flags,
                        country_trackers,
                    )
                }))
            };
            let division_handle = if divisions_enabled {
                Some(scope.spawn(move || {
                    read_compact_divisions(
                        state,
                        control,
                        status_flags,
                        division_tracker,
                        division_roots,
                    )
                }))
            } else {
                None
            };
            let division_equipment_handle = if division_equipment_enabled {
                Some(scope.spawn(move || {
                    read_compact_division_equipment(
                        state,
                        control,
                        status_flags,
                        division_equipment_tracker,
                        division_roots,
                    )
                }))
            } else {
                None
            };
            let army_order_handle = if army_orders_enabled {
                Some(scope.spawn(move || {
                    read_compact_army_orders(
                        state,
                        status_flags,
                        army_order_tracker,
                        division_roots,
                    )
                }))
            } else {
                None
            };
            let land_combat_handle = if land_combats_enabled {
                Some(scope.spawn(move || {
                    read_compact_land_combats(state, status_flags, land_combat_tracker)
                }))
            } else {
                None
            };
            let map_control_handle = if map_control_enabled {
                Some(scope.spawn(move || {
                    read_compact_map_control(state, status_flags, map_control_tracker)
                }))
            } else {
                None
            };
            let map_detail_handle = if map_detail_enabled {
                Some(scope.spawn(move || {
                    read_compact_map_detail(
                        state,
                        status_flags,
                        map_detail_include_resources,
                        map_detail_include_buildings,
                        map_detail_tracker,
                    )
                }))
            } else {
                None
            };
            let weather_handle = if weather_enabled {
                Some(
                    scope.spawn(move || read_compact_weather(state, status_flags, weather_tracker)),
                )
            } else {
                None
            };

            if let Some(handle) = country_handle {
                country_reads = match handle.join() {
                    Ok(reads) => reads,
                    Err(_) => vec![compact_worker_panic_read(
                        country_specs_for_panic,
                        status_flags,
                    )],
                };
            }
            if let Some(handle) = division_handle {
                division_read = Some(match handle.join() {
                    Ok(read) => read,
                    Err(_) => compact_division_worker_panic_read(control, status_flags),
                });
            }
            if let Some(handle) = division_equipment_handle {
                division_equipment_read = Some(match handle.join() {
                    Ok(read) => read,
                    Err(_) => compact_division_equipment_worker_panic_read(control, status_flags),
                });
            }
            if let Some(handle) = army_order_handle {
                army_order_read = Some(match handle.join() {
                    Ok(read) => read,
                    Err(_) => compact_army_order_worker_panic_read(division_roots, status_flags),
                });
            }
            if let Some(handle) = land_combat_handle {
                land_combat_read = Some(match handle.join() {
                    Ok(read) => read,
                    Err(_) => compact_land_combat_worker_panic_read(status_flags),
                });
            }
            if let Some(handle) = map_control_handle {
                map_control_read = Some(match handle.join() {
                    Ok(read) => read,
                    Err(_) => compact_map_control_worker_panic_read(status_flags),
                });
            }
            if let Some(handle) = map_detail_handle {
                map_detail_read = Some(match handle.join() {
                    Ok(read) => read,
                    Err(_) => compact_map_detail_worker_panic_read(status_flags),
                });
            }
            if let Some(handle) = weather_handle {
                weather_read = Some(match handle.join() {
                    Ok(read) => read,
                    Err(_) => compact_weather_worker_panic_read(status_flags),
                });
            }
        });

        for read in country_reads.drain(..) {
            for spec in read.specs {
                let changed_rows = read
                    .rows
                    .iter()
                    .filter(|row| row_has_compact_domain(row, spec.kind))
                    .count();
                let unit_count = compact_domain_unit_count(&read.rows, spec.kind);
                append_compact_domain_perf_record(
                    &mut out,
                    sequence,
                    game_hour_raw,
                    CompactDomainPerfRecord {
                        domain_id: spec.id,
                        read_time_us: read.read_time_us,
                        row_count: read.row_count,
                        changed_rows: changed_rows.min(u32::MAX as usize) as u32,
                        unit_count,
                        changed_unit_count: unit_count,
                        status_flags: read.status_flags,
                    },
                    elapsed_wall_ms,
                );
                sequence = sequence.saturating_add(1);
                let emitted_data = match spec.kind {
                    CompactCountryDomainKind::Fuel => append_compact_fuel_data_record(
                        &mut out,
                        sequence,
                        game_hour_raw,
                        &read.rows,
                        elapsed_wall_ms,
                        read.status_flags,
                    ),
                    CompactCountryDomainKind::Production => append_compact_production_data_record(
                        &mut out,
                        sequence,
                        game_hour_raw,
                        &read.rows,
                        elapsed_wall_ms,
                        read.status_flags,
                    ),
                    CompactCountryDomainKind::Focus => append_compact_focus_data_record(
                        &mut out,
                        sequence,
                        game_hour_raw,
                        &read.rows,
                        elapsed_wall_ms,
                        read.status_flags,
                    ),
                    CompactCountryDomainKind::Tech => append_compact_tech_data_record(
                        &mut out,
                        sequence,
                        game_hour_raw,
                        &read.rows,
                        elapsed_wall_ms,
                        read.status_flags,
                    ),
                    CompactCountryDomainKind::Politics => append_compact_politics_data_record(
                        &mut out,
                        sequence,
                        game_hour_raw,
                        &read.rows,
                        elapsed_wall_ms,
                        read.status_flags,
                    ),
                    CompactCountryDomainKind::PoliticsResiduals => {
                        append_compact_politics_residuals_data_record(
                            &mut out,
                            sequence,
                            game_hour_raw,
                            &read.rows,
                            elapsed_wall_ms,
                            read.status_flags,
                        )
                    }
                    CompactCountryDomainKind::Decisions => append_compact_decisions_data_record(
                        &mut out,
                        sequence,
                        game_hour_raw,
                        &read.rows,
                        elapsed_wall_ms,
                        read.status_flags,
                    ),
                    CompactCountryDomainKind::Diplomacy => append_compact_diplomacy_data_record(
                        &mut out,
                        sequence,
                        game_hour_raw,
                        &read.rows,
                        elapsed_wall_ms,
                        read.status_flags,
                    ),
                };
                if emitted_data {
                    sequence = sequence.saturating_add(1);
                }
                emitted_domains = emitted_domains.saturating_add(1);
            }
        }
        if let Some(read) = division_read {
            append_compact_domain_perf_record(
                &mut out,
                sequence,
                game_hour_raw,
                CompactDomainPerfRecord {
                    domain_id: COMPACT_DOMAIN_DIVISIONS,
                    read_time_us: read.read_time_us,
                    row_count: read.root_rows,
                    changed_rows: read.changed_rows,
                    unit_count: read.root_rows,
                    changed_unit_count: read.changed_rows,
                    status_flags: read.status_flags,
                },
                elapsed_wall_ms,
            );
            sequence = sequence.saturating_add(1);
            append_compact_divisions_data_record(
                &mut out,
                sequence,
                game_hour_raw,
                &read.rows,
                elapsed_wall_ms,
                read.status_flags,
                read.changed_rows,
                read.root_rows,
            );
            sequence = sequence.saturating_add(1);
            emitted_domains = emitted_domains.saturating_add(1);
        }
        if let Some(read) = division_equipment_read {
            append_compact_domain_perf_record(
                &mut out,
                sequence,
                game_hour_raw,
                CompactDomainPerfRecord {
                    domain_id: COMPACT_DOMAIN_DIVISION_EQUIPMENT,
                    read_time_us: read.read_time_us,
                    row_count: read.observed_division_rows,
                    changed_rows: read.changed_rows,
                    unit_count: read.observed_equipment_rows,
                    changed_unit_count: read.emitted_equipment_rows,
                    status_flags: read.status_flags,
                },
                elapsed_wall_ms,
            );
            sequence = sequence.saturating_add(1);
            append_compact_division_equipment_data_record(
                &mut out,
                sequence,
                game_hour_raw,
                &read.rows,
                elapsed_wall_ms,
                read.status_flags,
                read.changed_rows,
                read.root_rows,
                read.observed_division_rows,
                read.observed_equipment_rows,
            );
            sequence = sequence.saturating_add(1);
            emitted_domains = emitted_domains.saturating_add(1);
        }
        if let Some(read) = army_order_read {
            append_compact_domain_perf_record(
                &mut out,
                sequence,
                game_hour_raw,
                CompactDomainPerfRecord {
                    domain_id: COMPACT_DOMAIN_ARMY_ORDERS,
                    read_time_us: read.read_time_us,
                    row_count: read.observed_army_rows,
                    changed_rows: read.changed_rows,
                    unit_count: read.observed_order_rows,
                    changed_unit_count: read.target_state_rows,
                    status_flags: read.status_flags,
                },
                elapsed_wall_ms,
            );
            sequence = sequence.saturating_add(1);
            append_compact_army_orders_data_record(
                &mut out,
                sequence,
                game_hour_raw,
                &read.rows,
                elapsed_wall_ms,
                read.status_flags,
                read.changed_rows,
                read.root_rows,
                read.observed_army_rows,
                read.observed_order_rows,
                read.deleted_rows,
            );
            sequence = sequence.saturating_add(1);
            emitted_domains = emitted_domains.saturating_add(1);
        }
        if let Some(read) = map_detail_read {
            append_compact_domain_perf_record(
                &mut out,
                sequence,
                game_hour_raw,
                CompactDomainPerfRecord {
                    domain_id: COMPACT_DOMAIN_MAP_DETAIL,
                    read_time_us: read.read_time_us,
                    row_count: read
                        .observed_state_rows
                        .saturating_add(read.observed_province_rows),
                    changed_rows: read.changed_rows,
                    unit_count: read
                        .observed_state_rows
                        .saturating_add(read.observed_province_rows),
                    changed_unit_count: read.changed_rows,
                    status_flags: read.status_flags,
                },
                elapsed_wall_ms,
            );
            sequence = sequence.saturating_add(1);
            append_compact_map_detail_data_record(
                &mut out,
                sequence,
                game_hour_raw,
                &read.state_rows,
                &read.province_rows,
                elapsed_wall_ms,
                read.status_flags,
                read.changed_rows,
                read.observed_state_rows,
                read.observed_province_rows,
            );
            sequence = sequence.saturating_add(1);
            emitted_domains = emitted_domains.saturating_add(1);
        }
        if let Some(read) = weather_read {
            append_compact_domain_perf_record(
                &mut out,
                sequence,
                game_hour_raw,
                CompactDomainPerfRecord {
                    domain_id: COMPACT_DOMAIN_WEATHER,
                    read_time_us: read.read_time_us,
                    row_count: read.observed_rows,
                    changed_rows: read.changed_rows,
                    unit_count: read.observed_rows,
                    changed_unit_count: read.changed_rows,
                    status_flags: read.status_flags,
                },
                elapsed_wall_ms,
            );
            sequence = sequence.saturating_add(1);
            append_compact_weather_data_record(
                &mut out,
                sequence,
                game_hour_raw,
                &read.rows,
                elapsed_wall_ms,
                read.status_flags,
                read.changed_rows,
                read.observed_rows,
            );
            sequence = sequence.saturating_add(1);
            emitted_domains = emitted_domains.saturating_add(1);
        }
        if let Some(read) = land_combat_read {
            append_compact_domain_perf_record(
                &mut out,
                sequence,
                game_hour_raw,
                CompactDomainPerfRecord {
                    domain_id: COMPACT_DOMAIN_LAND_COMBATS,
                    read_time_us: read.read_time_us,
                    row_count: read.rows.len().min(u32::MAX as usize) as u32,
                    changed_rows: read.changed_rows,
                    unit_count: read.participant_count,
                    changed_unit_count: read.changed_rows,
                    status_flags: read.status_flags,
                },
                elapsed_wall_ms,
            );
            sequence = sequence.saturating_add(1);
            append_compact_land_combats_data_record(
                &mut out,
                sequence,
                game_hour_raw,
                &read.rows,
                elapsed_wall_ms,
                read.status_flags,
                read.changed_rows,
                read.participant_count,
                read.ended_count,
            );
            sequence = sequence.saturating_add(1);
            emitted_domains = emitted_domains.saturating_add(1);
        }
        if let Some(read) = map_control_read {
            append_compact_domain_perf_record(
                &mut out,
                sequence,
                game_hour_raw,
                CompactDomainPerfRecord {
                    domain_id: COMPACT_DOMAIN_MAP_CONTROL,
                    read_time_us: read.read_time_us,
                    row_count: read
                        .observed_state_rows
                        .saturating_add(read.observed_province_rows),
                    changed_rows: read.changed_rows,
                    unit_count: read.observed_province_rows,
                    changed_unit_count: read.changed_province_rows,
                    status_flags: read.status_flags,
                },
                elapsed_wall_ms,
            );
            sequence = sequence.saturating_add(1);
            append_compact_map_control_data_record(
                &mut out,
                sequence,
                game_hour_raw,
                &read.state_rows,
                &read.province_rows,
                elapsed_wall_ms,
                read.status_flags,
                read.changed_rows,
                read.changed_state_rows,
                read.changed_province_rows,
            );
            sequence = sequence.saturating_add(1);
            emitted_domains = emitted_domains.saturating_add(1);
        }
        append_compact_frame_end_record(
            &mut out,
            sequence,
            game_hour_raw,
            elapsed_wall_ms,
            duration_micros_u64(frame_started.elapsed()),
            emitted_domains,
            emitted_domains,
            status_flags,
        );
        (out, sequence.saturating_add(1))
    }

    fn compact_parallel_gate_eligible(specs: &[CompactCountryDomainSpec]) -> bool {
        compact_parallel_gate_lanes(specs.iter().copied()).lane_count() > 1
    }

    fn compact_explicit_domain_enabled(control: &CollectorControl, domain: &str) -> bool {
        control.scheduled_domains_valid
            && control
                .scheduled_domains
                .iter()
                .any(|scheduled| scheduled == domain)
    }

    fn compact_map_control_enabled(control: &CollectorControl) -> bool {
        control.scheduled_domains_valid
            && control.scheduled_domains.iter().any(|scheduled| {
                scheduled == RAW_MAP_CONTROL_DOMAIN
                    || scheduled == "state_ownership"
                    || scheduled == "state_control"
                    || scheduled == "province_control"
            })
    }

    fn compact_map_detail_enabled(control: &CollectorControl) -> bool {
        control.scheduled_domains_valid
            && control.scheduled_domains.iter().any(|scheduled| {
                scheduled == "map_detail"
                    || scheduled == "state_detail"
                    || scheduled == "buildings_live"
            })
    }

    fn compact_weather_enabled(control: &CollectorControl) -> bool {
        control.scheduled_domains_valid
            && control
                .scheduled_domains
                .iter()
                .any(|scheduled| scheduled == "weather_live")
    }

    fn compact_map_detail_include_buildings(control: &CollectorControl) -> bool {
        control.scheduled_domains_valid
            && control
                .scheduled_domains
                .iter()
                .any(|scheduled| scheduled == "map_detail" || scheduled == "buildings_live")
    }

    fn compact_map_detail_include_resources(control: &CollectorControl) -> bool {
        control.scheduled_domains_valid
            && control
                .scheduled_domains
                .iter()
                .any(|scheduled| scheduled == "map_detail" || scheduled == "state_detail")
    }

    fn read_compact_country_domain_bundles(
        state: &CollectorState,
        control: &CollectorControl,
        specs: Vec<CompactCountryDomainSpec>,
        status_flags: u32,
        trackers: CompactCountryGateTrackers<'_>,
    ) -> Vec<CompactBundleRead> {
        if compact_parallel_gate_eligible(&specs) {
            read_compact_country_domain_bundles_parallel(
                state,
                control,
                specs,
                status_flags,
                trackers,
            )
        } else {
            vec![read_compact_country_domain_bundle(
                state,
                control,
                specs,
                status_flags,
                trackers.combined,
            )]
        }
    }

    fn read_compact_country_domain_bundles_parallel(
        state: &CollectorState,
        control: &CollectorControl,
        specs: Vec<CompactCountryDomainSpec>,
        status_flags: u32,
        trackers: CompactCountryGateTrackers<'_>,
    ) -> Vec<CompactBundleRead> {
        let CompactParallelSpecs {
            fuel,
            production,
            focus_tech,
            politics,
            politics_residuals,
            decisions,
            diplomacy,
        } = compact_parallel_gate_lanes(specs);
        let fuel_specs_for_panic = fuel.clone();
        let production_specs_for_panic = production.clone();
        let focus_tech_specs_for_panic = focus_tech.clone();
        let politics_specs_for_panic = politics.clone();
        let politics_residuals_specs_for_panic = politics_residuals.clone();
        let decisions_specs_for_panic = decisions.clone();
        let diplomacy_specs_for_panic = diplomacy.clone();
        let CompactCountryGateTrackers {
            fuel: fuel_tracker,
            production: production_tracker,
            focus_tech: focus_tech_tracker,
            politics: politics_tracker,
            politics_residuals: politics_residuals_tracker,
            decisions: decisions_tracker,
            diplomacy: diplomacy_tracker,
            combined: _,
        } = trackers;
        let mut fuel_read = None;
        let mut production_read = None;
        let mut focus_tech_read = None;
        let mut politics_read = None;
        let mut politics_residuals_read = None;
        let mut decisions_read = None;
        let mut diplomacy_read = None;
        thread::scope(|scope| {
            let fuel_handle = if fuel.is_empty() {
                None
            } else {
                Some(scope.spawn(|| {
                    read_compact_country_domain_bundle(
                        state,
                        control,
                        fuel,
                        status_flags,
                        fuel_tracker,
                    )
                }))
            };
            let production_handle = if production.is_empty() {
                None
            } else {
                Some(scope.spawn(|| {
                    read_compact_country_domain_bundle(
                        state,
                        control,
                        production,
                        status_flags,
                        production_tracker,
                    )
                }))
            };
            let focus_tech_handle = if focus_tech.is_empty() {
                None
            } else {
                Some(scope.spawn(|| {
                    read_compact_country_domain_bundle(
                        state,
                        control,
                        focus_tech,
                        status_flags,
                        focus_tech_tracker,
                    )
                }))
            };
            let politics_handle = if politics.is_empty() {
                None
            } else {
                Some(scope.spawn(|| {
                    read_compact_country_domain_bundle(
                        state,
                        control,
                        politics,
                        status_flags,
                        politics_tracker,
                    )
                }))
            };
            let politics_residuals_handle = if politics_residuals.is_empty() {
                None
            } else {
                Some(scope.spawn(|| {
                    read_compact_country_domain_bundle(
                        state,
                        control,
                        politics_residuals,
                        status_flags,
                        politics_residuals_tracker,
                    )
                }))
            };
            let decisions_handle = if decisions.is_empty() {
                None
            } else {
                Some(scope.spawn(|| {
                    read_compact_country_domain_bundle(
                        state,
                        control,
                        decisions,
                        status_flags,
                        decisions_tracker,
                    )
                }))
            };
            let diplomacy_handle = if diplomacy.is_empty() {
                None
            } else {
                Some(scope.spawn(|| {
                    read_compact_country_domain_bundle(
                        state,
                        control,
                        diplomacy,
                        status_flags,
                        diplomacy_tracker,
                    )
                }))
            };
            if let Some(handle) = fuel_handle {
                fuel_read = Some(match handle.join() {
                    Ok(read) => read,
                    Err(_) => compact_worker_panic_read(fuel_specs_for_panic, status_flags),
                });
            }
            if let Some(handle) = production_handle {
                production_read = Some(match handle.join() {
                    Ok(read) => read,
                    Err(_) => compact_worker_panic_read(production_specs_for_panic, status_flags),
                });
            }
            if let Some(handle) = focus_tech_handle {
                focus_tech_read = Some(match handle.join() {
                    Ok(read) => read,
                    Err(_) => compact_worker_panic_read(focus_tech_specs_for_panic, status_flags),
                });
            }
            if let Some(handle) = politics_handle {
                politics_read = Some(match handle.join() {
                    Ok(read) => read,
                    Err(_) => compact_worker_panic_read(politics_specs_for_panic, status_flags),
                });
            }
            if let Some(handle) = politics_residuals_handle {
                politics_residuals_read = Some(match handle.join() {
                    Ok(read) => read,
                    Err(_) => {
                        compact_worker_panic_read(politics_residuals_specs_for_panic, status_flags)
                    }
                });
            }
            if let Some(handle) = decisions_handle {
                decisions_read = Some(match handle.join() {
                    Ok(read) => read,
                    Err(_) => compact_worker_panic_read(decisions_specs_for_panic, status_flags),
                });
            }
            if let Some(handle) = diplomacy_handle {
                diplomacy_read = Some(match handle.join() {
                    Ok(read) => read,
                    Err(_) => compact_worker_panic_read(diplomacy_specs_for_panic, status_flags),
                });
            }
        });
        [
            fuel_read,
            production_read,
            focus_tech_read,
            politics_read,
            politics_residuals_read,
            decisions_read,
            diplomacy_read,
        ]
        .into_iter()
        .flatten()
        .collect()
    }

    fn compact_parallel_gate_lanes<I>(specs: I) -> CompactParallelSpecs
    where
        I: IntoIterator<Item = CompactCountryDomainSpec>,
    {
        let mut lanes = CompactParallelSpecs::default();
        for spec in specs {
            match spec.kind {
                CompactCountryDomainKind::Fuel => lanes.fuel.push(spec),
                CompactCountryDomainKind::Production => lanes.production.push(spec),
                CompactCountryDomainKind::Focus | CompactCountryDomainKind::Tech => {
                    lanes.focus_tech.push(spec)
                }
                CompactCountryDomainKind::Politics => lanes.politics.push(spec),
                CompactCountryDomainKind::PoliticsResiduals => lanes.politics_residuals.push(spec),
                CompactCountryDomainKind::Decisions => lanes.decisions.push(spec),
                CompactCountryDomainKind::Diplomacy => lanes.diplomacy.push(spec),
            }
        }
        lanes
    }

    fn compact_bundle_is_politics_only(specs: &[CompactCountryDomainSpec]) -> bool {
        matches!(
            specs,
            [CompactCountryDomainSpec {
                kind: CompactCountryDomainKind::Politics,
                ..
            }]
        )
    }

    fn compact_politics_shard_count(row_count: usize) -> usize {
        if row_count < COMPACT_POLITICS_SHARD_MIN_ROWS.saturating_mul(2) {
            return 1;
        }
        let target_shards =
            (row_count + COMPACT_POLITICS_SHARD_MIN_ROWS - 1) / COMPACT_POLITICS_SHARD_MIN_ROWS;
        let available = thread::available_parallelism()
            .map(|parallelism| parallelism.get())
            .unwrap_or(1);
        target_shards
            .min(available)
            .min(COMPACT_POLITICS_SHARD_MAX_WORKERS)
            .max(1)
    }

    fn compact_politics_shard_rows(
        rows: &[CountryObjectRow],
        country_vtable: usize,
        idea_group_filter: Option<&BTreeMap<String, String>>,
        tracker: &CompactCountryFrameTracker,
    ) -> CompactPoliticsShardRead {
        let mut read = CompactPoliticsShardRead::default();
        for row in rows {
            if let Some((fresh, politics_update, popularity_update)) =
                compact_politics_shard_row_expected(row, country_vtable, idea_group_filter, tracker)
            {
                if let Some((fingerprint, politics)) = politics_update {
                    read.politics_updates
                        .push((fresh.tag_db_id, fingerprint, politics));
                }
                if let Some(fingerprint) = popularity_update {
                    read.popularity_updates.push((fresh.tag_db_id, fingerprint));
                }
                read.rows.push(fresh);
            }
        }
        read
    }

    fn compact_politics_shard_row_expected(
        expected: &CountryObjectRow,
        country_vtable: usize,
        idea_group_filter: Option<&BTreeMap<String, String>>,
        tracker: &CompactCountryFrameTracker,
    ) -> Option<(
        CountryObjectRow,
        Option<(CountryPoliticsFingerprint, Option<CountryPoliticsRow>)>,
        Option<u64>,
    )> {
        let object_ptr = expected.object_ptr;
        if read_u64(object_ptr)? as usize != country_vtable {
            return None;
        }
        let tag_db_id = read_u32(object_ptr + OBJ_TAG_DB_ID)?;
        if tag_db_id != expected.tag_db_id {
            return None;
        }
        let previously_seen = tracker.previous_rows.contains_key(&expected.tag);
        let fingerprint = read_country_politics_change_fingerprint(object_ptr, country_vtable);
        let (structural_changed, popularity_changed) = if previously_seen {
            match fingerprint.as_ref() {
                Some(fingerprint) => {
                    let structural_changed = tracker
                        .country_politics
                        .get(&expected.tag_db_id)
                        .map(|(cached, _, _)| cached != &fingerprint.structural)
                        .unwrap_or(true);
                    let popularity_changed = tracker
                        .country_politics_popularity
                        .get(&expected.tag_db_id)
                        .map(|cached| cached != &fingerprint.popularity_hash)
                        .unwrap_or(true);
                    (structural_changed, popularity_changed)
                }
                None => (true, true),
            }
        } else {
            (true, true)
        };
        if !structural_changed && !popularity_changed {
            return None;
        }

        let mut row = compact_country_delta_row_shell(expected, tag_db_id);
        let mut politics_update = None;
        let mut popularity_update = None;
        if structural_changed {
            let politics =
                read_country_politics(object_ptr, country_vtable, idea_group_filter, true);
            row.politics = politics.clone();
            if let Some(fingerprint) = fingerprint {
                politics_update = Some((fingerprint.structural, politics));
                popularity_update = Some(fingerprint.popularity_hash);
            }
        } else {
            let politics = read_country_politics_popularity_delta(object_ptr, country_vtable);
            row.politics = politics;
            if let Some(fingerprint) = fingerprint {
                popularity_update = Some(fingerprint.popularity_hash);
            }
        }
        if row.politics.is_some() {
            Some((row, politics_update, popularity_update))
        } else {
            None
        }
    }

    fn compact_country_delta_row_shell(
        expected: &CountryObjectRow,
        tag_db_id: u32,
    ) -> CountryObjectRow {
        CountryObjectRow {
            tag: expected.tag.clone(),
            tag_db_id,
            name: expected.name.clone(),
            object_ptr: expected.object_ptr,
            record_ptr: expected.record_ptr,
            original_capital: None,
            original_tag: None,
            templates_locked: None,
            reserved_dynamic_country: None,
            stability: None,
            war_support: None,
            political_power: None,
            command_power: None,
            num_ships: None,
            manpower_pool: None,
            convoys: None,
            misc: None,
            fuel: None,
            production: None,
            focus: None,
            research: None,
            politics: None,
            politics_residuals: None,
            decisions: None,
            diplomacy: None,
        }
    }

    fn compact_worker_panic_read(
        specs: Vec<CompactCountryDomainSpec>,
        status_flags: u32,
    ) -> CompactBundleRead {
        CompactBundleRead {
            specs,
            rows: Vec::new(),
            read_time_us: 0,
            row_count: 0,
            status_flags: status_flags | COMPACT_STATUS_WORKER_PANIC,
        }
    }

    fn compact_division_worker_panic_read(
        control: &CollectorControl,
        status_flags: u32,
    ) -> CompactDivisionRead {
        CompactDivisionRead {
            rows: Vec::new(),
            read_time_us: 0,
            changed_rows: 0,
            status_flags: status_flags | COMPACT_STATUS_WORKER_PANIC,
            root_rows: control.division_body_bridge.len().min(u32::MAX as usize) as u32,
        }
    }

