    fn prewarm_compact_division_roots(
        state: Option<&CollectorState>,
        control: &CollectorControl,
        root_cache: &mut CompactDivisionRootCache,
    ) {
        if control.stream_format != CollectorStreamFormat::Compact
            || !compact_division_roots_enabled(control)
        {
            return;
        }
        if compact_division_bridge_available(control) {
            return;
        }
        *root_cache = discover_compact_division_roots(state);
    }

    fn compact_division_roots_enabled(control: &CollectorControl) -> bool {
        compact_explicit_domain_enabled(control, RAW_DIVISIONS_DOMAIN)
            || compact_explicit_domain_enabled(control, RAW_DIVISION_EQUIPMENT_DOMAIN)
            || compact_explicit_domain_enabled(control, RAW_ARMY_ORDERS_DOMAIN)
    }

    fn compact_division_bridge_available(control: &CollectorControl) -> bool {
        control.division_body_bridge_valid
            && division_body_bridge_well_formed(&control.division_body_bridge)
            && !control.division_body_bridge.is_empty()
    }

    fn discover_compact_division_roots(state: Option<&CollectorState>) -> CompactDivisionRootCache {
        let mut cache = CompactDivisionRootCache { rows: Vec::new() };
        if let Some(rows) = state.and_then(discover_compact_division_roots_from_countries) {
            cache.rows = rows;
        }
        cache
    }

    fn discover_compact_division_roots_from_countries(
        state: &CollectorState,
    ) -> Option<Vec<DivisionBodyBridgeEntry>> {
        if state.base == 0 || !state.daily_match || !state.long_string_match {
            return None;
        }
        let module_base = state.base;
        let game_state = state.date_ptr as usize;
        if !is_heap_pointer_aligned(game_state, 8) {
            return None;
        }
        let country_table = read_u64(game_state.checked_add(CGAMESTATE_COUNTRY_TABLE)?)? as usize;
        let country_count = read_u32(game_state.checked_add(CGAMESTATE_COUNTRY_COUNT)?)?;
        if country_count == 0 || country_count > MAX_CGAMESTATE_COUNTRIES {
            return None;
        }
        if !is_heap_pointer_aligned(country_table, 8) {
            return None;
        }
        let table_len = (country_count as usize).checked_mul(8)?;
        let country_ptrs = read_bytes(country_table, table_len)?;
        let country_vtable = module_base.checked_add(COUNTRY_VTABLE_RVA)?;
        let wrapper_vtable = module_base.checked_add(DIVISION_WRAPPER_VTABLE_RVA)?;
        let division_vtable = module_base.checked_add(DIVISION_VTABLE_RVA)?;
        let mut rows_by_id: BTreeMap<u32, DivisionBodyBridgeEntry> = BTreeMap::new();

        for index in 0..country_count as usize {
            if rows_by_id.len() >= MAX_DIVISION_BODY_BRIDGE_ROWS {
                break;
            }
            let Some(country_ptr) = read_u64_from_slice(&country_ptrs, index * 8) else {
                continue;
            };
            let country_ptr = country_ptr as usize;
            if !is_heap_pointer_aligned(country_ptr, 8) {
                continue;
            }
            if read_u64(country_ptr).map(|value| value as usize) != Some(country_vtable) {
                continue;
            }
            collect_compact_division_country_roots(
                country_ptr,
                index as u32,
                wrapper_vtable,
                division_vtable,
                &mut rows_by_id,
            );
        }

        if rows_by_id.is_empty() {
            None
        } else {
            Some(rows_by_id.into_values().collect())
        }
    }

    fn collect_compact_division_country_roots(
        country_ptr: usize,
        owner_tag_db_id: u32,
        wrapper_vtable: usize,
        division_vtable: usize,
        rows_by_id: &mut BTreeMap<u32, DivisionBodyBridgeEntry>,
    ) {
        let Some(vector_data) = read_u64(country_ptr.saturating_add(COUNTRY_DIVISION_WRAPPER_DATA))
        else {
            return;
        };
        let Some(capacity) =
            read_u32(country_ptr.saturating_add(COUNTRY_DIVISION_WRAPPER_CAPACITY))
        else {
            return;
        };
        let Some(count) = read_u32(country_ptr.saturating_add(COUNTRY_DIVISION_WRAPPER_COUNT))
        else {
            return;
        };
        if count == 0 {
            return;
        }
        if count > capacity || count > MAX_COUNTRY_DIVISION_WRAPPER_ROWS {
            return;
        }
        let vector_data = vector_data as usize;
        if !is_heap_pointer_aligned(vector_data, 8) {
            return;
        }
        let Some(byte_len) = (count as usize).checked_mul(8) else {
            return;
        };
        let Some(wrapper_ptrs) = read_bytes(vector_data, byte_len) else {
            return;
        };
        for index in 0..count as usize {
            if rows_by_id.len() >= MAX_DIVISION_BODY_BRIDGE_ROWS {
                break;
            }
            let Some(wrapper_ptr) = read_u64_from_slice(&wrapper_ptrs, index * 8) else {
                continue;
            };
            let wrapper_ptr = wrapper_ptr as usize;
            if !is_heap_pointer_aligned(wrapper_ptr, 8) {
                continue;
            }
            if read_u64(wrapper_ptr).map(|value| value as usize) != Some(wrapper_vtable) {
                continue;
            }
            let Some(body_ptr) = wrapper_ptr.checked_add(DIVISION_WRAPPER_TO_BODY) else {
                continue;
            };
            let Some(div_id) = validate_compact_division_body_root(body_ptr, division_vtable)
            else {
                continue;
            };
            rows_by_id.entry(div_id).or_insert(DivisionBodyBridgeEntry {
                div_id,
                body_ptr,
                owner_tag_db_id,
            });
        }
    }

    fn validate_compact_division_body_root(body_ptr: usize, division_vtable: usize) -> Option<u32> {
        if !is_heap_pointer_aligned(body_ptr, 8) {
            return None;
        }
        if read_u64(body_ptr)? as usize != division_vtable {
            return None;
        }
        if !is_compact_division_body_type(read_u32(body_ptr.checked_add(DIVISION_OFF_ID_TYPE)?)?) {
            return None;
        }
        let div_id = read_u32(body_ptr.checked_add(DIVISION_OFF_ID_ID)?)?;
        if div_id == 0 || div_id > MAX_DIVISION_BODY_BRIDGE_DIV_ID {
            return None;
        }
        Some(div_id)
    }

    fn is_compact_division_body_type(unit_type: u32) -> bool {
        unit_type == DIVISION_TYPE || unit_type == DIVISION_ALT_UNIT_TYPE
    }

    fn read_compact_divisions(
        state: &CollectorState,
        control: &CollectorControl,
        status_flags: u32,
        tracker: &mut BTreeMap<u32, DivisionMovementSample>,
        root_cache: &CompactDivisionRootCache,
    ) -> CompactDivisionRead {
        let read_started = Instant::now();
        let mut status_flags = status_flags;
        let bridge_available = compact_division_bridge_available(control);
        let (root_rows, active_rows) = if bridge_available {
            let roots = &control.division_body_bridge;
            (
                roots.len().min(u32::MAX as usize) as u32,
                sample_compact_division_roots(state.base, roots),
            )
        } else {
            let root_count = root_cache.rows.len();
            let rows = sample_compact_division_roots(state.base, &root_cache.rows);
            let _candidate_root_count = root_count;
            // For native anchored discovery, root_rows is the count of fully
            // sampled and validated typed roots. Candidate wrapper pointers can
            // churn while the game is running; invalid candidates fail closed
            // by omission instead of marking a durable replay frame partial.
            (rows.len().min(u32::MAX as usize) as u32, rows)
        };
        if root_rows == 0 {
            status_flags |= COMPACT_STATUS_SOURCE_UNAVAILABLE;
            return CompactDivisionRead {
                rows: Vec::new(),
                read_time_us: duration_micros_u64(read_started.elapsed()),
                changed_rows: 0,
                status_flags,
                root_rows,
            };
        }

        if active_rows.is_empty() {
            status_flags |= COMPACT_STATUS_SOURCE_UNAVAILABLE;
            return CompactDivisionRead {
                rows: Vec::new(),
                read_time_us: duration_micros_u64(read_started.elapsed()),
                changed_rows: 0,
                status_flags,
                root_rows,
            };
        }
        if active_rows.len() < root_rows as usize {
            status_flags |= COMPACT_STATUS_PARTIAL_DATA;
            return CompactDivisionRead {
                changed_rows: active_rows.len().min(u32::MAX as usize) as u32,
                rows: active_rows,
                read_time_us: duration_micros_u64(read_started.elapsed()),
                status_flags,
                root_rows,
            };
        }

        let emit_full_snapshot = tracker.is_empty();
        let mut current = BTreeMap::new();
        let mut emitted_rows = Vec::new();
        let mut changed_rows = 0u32;
        for sample in active_rows {
            let changed = tracker
                .get(&sample.div_id)
                .map(|old| old != &sample)
                .unwrap_or(true);
            if changed {
                changed_rows = changed_rows.saturating_add(1);
            }
            if emit_full_snapshot || changed {
                emitted_rows.push(sample.clone());
            }
            current.insert(sample.div_id, sample);
        }
        if !emit_full_snapshot {
            let removed_ids = tracker
                .keys()
                .filter(|div_id| !current.contains_key(div_id))
                .copied()
                .collect::<Vec<_>>();
            for div_id in removed_ids {
                changed_rows = changed_rows.saturating_add(1);
                emitted_rows.push(deleted_division_sample(div_id));
            }
            status_flags |= COMPACT_STATUS_DELTA_DATA;
        }
        *tracker = current;

        CompactDivisionRead {
            rows: emitted_rows,
            read_time_us: duration_micros_u64(read_started.elapsed()),
            changed_rows,
            status_flags,
            root_rows,
        }
    }

    fn read_compact_division_equipment(
        state: &CollectorState,
        control: &CollectorControl,
        status_flags: u32,
        tracker: &mut CompactDivisionEquipmentTracker,
        root_cache: &CompactDivisionRootCache,
    ) -> CompactDivisionEquipmentRead {
        let read_started = Instant::now();
        let mut status_flags = status_flags;
        let bridge_available = compact_division_bridge_available(control);
        let roots = if bridge_available {
            &control.division_body_bridge
        } else {
            &root_cache.rows
        };
        let root_rows = roots.len().min(u32::MAX as usize) as u32;
        if roots.is_empty() {
            status_flags |= COMPACT_STATUS_SOURCE_UNAVAILABLE;
            return CompactDivisionEquipmentRead {
                rows: Vec::new(),
                read_time_us: duration_micros_u64(read_started.elapsed()),
                changed_rows: 0,
                status_flags,
                root_rows,
                observed_division_rows: 0,
                observed_equipment_rows: 0,
                emitted_equipment_rows: 0,
            };
        }

        let active_rows = sample_compact_division_equipment_roots(state.base, roots);
        let observed_division_rows = active_rows.len().min(u32::MAX as usize) as u32;
        let observed_equipment_rows =
            compact_division_equipment_entry_count(&active_rows).min(u32::MAX as usize) as u32;
        if active_rows.is_empty() {
            status_flags |= COMPACT_STATUS_SOURCE_UNAVAILABLE;
            return CompactDivisionEquipmentRead {
                rows: Vec::new(),
                read_time_us: duration_micros_u64(read_started.elapsed()),
                changed_rows: 0,
                status_flags,
                root_rows,
                observed_division_rows,
                observed_equipment_rows,
                emitted_equipment_rows: 0,
            };
        }
        if active_rows.len() < roots.len() {
            status_flags |= COMPACT_STATUS_PARTIAL_DATA;
        }

        let emit_full_snapshot = tracker.previous.is_empty();
        let mut current = BTreeMap::new();
        let mut emitted_rows = Vec::new();
        let mut changed_rows = 0u32;
        for sample in active_rows {
            let key = (sample.owner_tag_db_id, sample.div_id);
            let changed = tracker
                .previous
                .get(&key)
                .map(|old| old != &sample)
                .unwrap_or(true);
            if changed {
                changed_rows = changed_rows.saturating_add(1);
            }
            if emit_full_snapshot || changed {
                emitted_rows.push(sample.clone());
            }
            current.insert(key, sample);
        }
        if !emit_full_snapshot {
            let removed_keys = tracker
                .previous
                .keys()
                .filter(|key| !current.contains_key(key))
                .copied()
                .collect::<Vec<_>>();
            for (owner_tag_db_id, div_id) in removed_keys {
                changed_rows = changed_rows.saturating_add(1);
                emitted_rows.push(deleted_division_equipment_sample(owner_tag_db_id, div_id));
            }
            status_flags |= COMPACT_STATUS_DELTA_DATA;
        }
        emitted_rows.sort_by_key(|sample| (sample.owner_tag_db_id, sample.div_id));
        tracker.previous = current;
        let emitted_equipment_rows =
            compact_division_equipment_entry_count(&emitted_rows).min(u32::MAX as usize) as u32;

        CompactDivisionEquipmentRead {
            rows: emitted_rows,
            read_time_us: duration_micros_u64(read_started.elapsed()),
            changed_rows,
            status_flags,
            root_rows,
            observed_division_rows,
            observed_equipment_rows,
            emitted_equipment_rows,
        }
    }

    fn deleted_division_equipment_sample(
        owner_tag_db_id: u32,
        div_id: u32,
    ) -> DivisionEquipmentSample {
        DivisionEquipmentSample {
            owner_tag_db_id,
            div_id,
            deleted: true,
            template_id: None,
            entries: Vec::new(),
        }
    }

    fn compact_division_equipment_entry_count(rows: &[DivisionEquipmentSample]) -> usize {
        rows.iter().map(|row| row.entries.len()).sum()
    }

    fn read_compact_army_orders(
        state: &CollectorState,
        status_flags: u32,
        tracker: &mut ArmyOrderTracker,
        root_cache: &CompactDivisionRootCache,
    ) -> CompactArmyOrderRead {
        let read_started = Instant::now();
        let mut status_flags = status_flags;
        let root_rows = root_cache.rows.len().min(u32::MAX as usize) as u32;
        if root_cache.rows.is_empty() {
            status_flags |= COMPACT_STATUS_SOURCE_UNAVAILABLE;
            return CompactArmyOrderRead {
                rows: Vec::new(),
                read_time_us: duration_micros_u64(read_started.elapsed()),
                changed_rows: 0,
                status_flags,
                root_rows,
                observed_army_rows: 0,
                observed_order_rows: 0,
                target_state_rows: 0,
                deleted_rows: 0,
            };
        }

        let (army_roots, invalid_army_roots) =
            discover_compact_army_order_roots(state.base, &root_cache.rows);
        if invalid_army_roots > 0 {
            status_flags |= COMPACT_STATUS_PARTIAL_DATA;
        }
        let observed_army_rows = army_roots.len().min(u32::MAX as usize) as u32;
        if army_roots.is_empty() {
            status_flags |= COMPACT_STATUS_SOURCE_UNAVAILABLE;
            return CompactArmyOrderRead {
                rows: Vec::new(),
                read_time_us: duration_micros_u64(read_started.elapsed()),
                changed_rows: 0,
                status_flags,
                root_rows,
                observed_army_rows,
                observed_order_rows: 0,
                target_state_rows: 0,
                deleted_rows: 0,
            };
        }

        let mut current_samples = Vec::new();
        let mut invalid_order_armies = 0u32;
        let mut seen_orders: BTreeMap<usize, ()> = BTreeMap::new();
        for entry in &army_roots {
            match sample_army_orders_from_army_body(state.base, entry.army_id, entry.body_ptr) {
                Some(samples) => {
                    for sample in samples {
                        if seen_orders.insert(sample.order_addr, ()).is_none() {
                            current_samples.push(sample);
                        }
                    }
                }
                None => invalid_order_armies = invalid_order_armies.saturating_add(1),
            }
        }
        if invalid_order_armies > 0 {
            status_flags |= COMPACT_STATUS_PARTIAL_DATA;
        }
        if current_samples.is_empty() && invalid_order_armies >= observed_army_rows {
            status_flags |= COMPACT_STATUS_SOURCE_UNAVAILABLE;
        }
        current_samples
            .sort_by_key(|sample| (sample.army_id, sample.slot_index, sample.order_addr));
        let observed_order_rows = current_samples.len().min(u32::MAX as usize) as u32;
        let had_previous = !tracker.previous.is_empty();
        let (rows, changed_rows, deleted_rows) =
            compact_army_order_delta_rows(tracker, current_samples);
        let target_state_rows =
            compact_army_order_target_state_count(&rows).min(u32::MAX as usize) as u32;
        if had_previous && !rows.is_empty() {
            status_flags |= COMPACT_STATUS_DELTA_DATA;
        }

        CompactArmyOrderRead {
            rows,
            read_time_us: duration_micros_u64(read_started.elapsed()),
            changed_rows,
            status_flags,
            root_rows,
            observed_army_rows,
            observed_order_rows,
            target_state_rows,
            deleted_rows,
        }
    }

    fn discover_compact_army_order_roots(
        module_base: usize,
        division_roots: &[DivisionBodyBridgeEntry],
    ) -> (Vec<ArmyBodyBridgeEntry>, u32) {
        let mut by_army_id: BTreeMap<u32, usize> = BTreeMap::new();
        let mut invalid_rows = 0u32;
        for division in division_roots {
            let Some(army_ptr) =
                read_u64(division.body_ptr.saturating_add(DIVISION_OFF_ARMY_PARENT))
                    .map(|value| value as usize)
            else {
                continue;
            };
            if !is_map_control_heap_pointer(army_ptr) {
                continue;
            }
            let Some(army_id) = validate_army_body(module_base, army_ptr) else {
                invalid_rows = invalid_rows.saturating_add(1);
                continue;
            };
            if let Some(existing_ptr) = by_army_id.get(&army_id) {
                if *existing_ptr != army_ptr {
                    invalid_rows = invalid_rows.saturating_add(1);
                }
                continue;
            }
            by_army_id.insert(army_id, army_ptr);
            if by_army_id.len() >= MAX_ARMY_BODY_BRIDGE_ROWS {
                break;
            }
        }
        (
            by_army_id
                .into_iter()
                .map(|(army_id, body_ptr)| ArmyBodyBridgeEntry { army_id, body_ptr })
                .collect(),
            invalid_rows,
        )
    }

    fn compact_army_order_delta_rows(
        tracker: &mut ArmyOrderTracker,
        current_samples: Vec<ArmyOrderSample>,
    ) -> (Vec<CompactArmyOrderRow>, u32, u32) {
        let emit_full_snapshot = tracker.previous.is_empty();
        let previous = std::mem::take(&mut tracker.previous);
        let mut current: BTreeMap<usize, ArmyOrderSample> = BTreeMap::new();
        let mut generation_splits: BTreeMap<usize, ArmyOrderSample> = BTreeMap::new();
        for mut sample in current_samples {
            if let Some(old) = previous.get(&sample.order_addr) {
                if army_order_continues(old, &sample) {
                    sample.generation = old.generation;
                } else {
                    generation_splits.insert(sample.order_addr, old.clone());
                    sample.generation = tracker.next_generation;
                    tracker.next_generation = tracker.next_generation.saturating_add(1);
                }
            } else {
                sample.generation = tracker.next_generation;
                tracker.next_generation = tracker.next_generation.saturating_add(1);
            }
            current.insert(sample.order_addr, sample);
        }

        let mut rows = Vec::new();
        let mut deleted_rows = 0u32;
        for (order_addr, sample) in &current {
            if let Some(old) = generation_splits.get(order_addr) {
                rows.push(deleted_compact_army_order_row(old));
                deleted_rows = deleted_rows.saturating_add(1);
                rows.push(compact_army_order_row(sample));
                continue;
            }
            match previous.get(order_addr) {
                Some(old) => {
                    if army_order_changed_fields(old, sample).is_some() {
                        rows.push(compact_army_order_row(sample));
                    }
                }
                None => rows.push(compact_army_order_row(sample)),
            }
            if emit_full_snapshot && previous.contains_key(order_addr) {
                rows.push(compact_army_order_row(sample));
            }
        }
        if !emit_full_snapshot {
            for (order_addr, old_sample) in &previous {
                if current.contains_key(order_addr) {
                    continue;
                }
                rows.push(deleted_compact_army_order_row(old_sample));
                deleted_rows = deleted_rows.saturating_add(1);
            }
        }
        rows.sort_by_key(|row| (row.army_id, row.generation, row.slot_index, row.deleted));
        tracker.previous = current;
        let changed_rows = rows.len().min(u32::MAX as usize) as u32;
        (rows, changed_rows, deleted_rows)
    }

    fn compact_army_order_row(sample: &ArmyOrderSample) -> CompactArmyOrderRow {
        CompactArmyOrderRow {
            army_id: sample.army_id,
            generation: sample.generation,
            deleted: false,
            slot_index: sample.slot_index,
            order_type: sample.order_type,
            target_states: sample.target_states.clone(),
            target_state_count: sample.target_state_count,
            target_status: sample.target_status,
        }
    }

