    fn sample_compact_weather_with_retry(
        state: &CollectorState,
        attempts: usize,
    ) -> Result<Vec<CompactWeatherRegionRow>, &'static str> {
        let attempt_count = attempts.max(1);
        for attempt in 0..attempt_count {
            match sample_compact_weather_regions(state) {
                Ok(rows) => return Ok(rows),
                Err(err) if attempt + 1 == attempt_count => return Err(err),
                Err(_) => thread::yield_now(),
            }
        }
        Err("weather_retry_exhausted")
    }

    fn sample_compact_weather_regions(
        state: &CollectorState,
    ) -> Result<Vec<CompactWeatherRegionRow>, &'static str> {
        let root = state.weather;
        if root.manager == 0 || root.region_array == 0 || root.region_count != WEATHER_REGION_COUNT
        {
            return Err("weather_root_unavailable");
        }
        validate_compact_weather_root_header(state.base, root)?;
        let byte_len = WEATHER_REGION_STRIDE
            .checked_mul(root.region_count as usize)
            .ok_or("weather_region_array_overflow")?;
        let bytes = read_bytes(root.region_array, byte_len).ok_or("weather_region_array_read")?;
        let mut rows = Vec::with_capacity(root.region_count as usize);
        for index in 0..root.region_count as usize {
            let start = index
                .checked_mul(WEATHER_REGION_STRIDE)
                .ok_or("weather_region_offset_overflow")?;
            let end = start
                .checked_add(WEATHER_REGION_STRIDE)
                .ok_or("weather_region_slice_overflow")?;
            let body = bytes.get(start..end).ok_or("weather_region_slice")?;
            rows.push(read_compact_weather_region_row(
                state.base,
                body,
                index as u32,
            )?);
        }
        Ok(rows)
    }

    fn resolve_compact_weather_root(
        module_base: usize,
        gamestate: usize,
    ) -> Option<CompactWeatherRoot> {
        if !is_map_control_heap_pointer(gamestate) {
            return None;
        }
        let manager = read_u64(gamestate.checked_add(CGAMESTATE_WEATHER_MANAGER)?)? as usize;
        read_compact_weather_root_at(module_base, manager)
    }

    fn read_compact_weather_root_at(
        module_base: usize,
        manager: usize,
    ) -> Option<CompactWeatherRoot> {
        if !is_map_control_heap_pointer(manager) {
            return None;
        }
        if read_u64(manager)? as usize != module_base.checked_add(WEATHER_MANAGER_VTABLE_RVA)? {
            return None;
        }
        let root = compact_weather_root_from_header(manager)?;
        validate_compact_weather_root_rows(module_base, root).then_some(root)
    }

    fn validate_compact_weather_root_header(
        module_base: usize,
        root: CompactWeatherRoot,
    ) -> Result<(), &'static str> {
        if !is_map_control_heap_pointer(root.manager)
            || !is_map_control_heap_pointer(root.region_array)
            || root.region_count != WEATHER_REGION_COUNT
        {
            return Err("weather_root_invalid");
        }
        if read_u64(root.manager).map(|value| value as usize)
            != module_base.checked_add(WEATHER_MANAGER_VTABLE_RVA)
        {
            return Err("weather_manager_vtable");
        }
        let current = compact_weather_root_from_header(root.manager)
            .ok_or("weather_region_header_unavailable")?;
        if current.region_array != root.region_array || current.region_count != root.region_count {
            return Err("weather_region_header_changed");
        }
        Ok(())
    }

    fn compact_weather_root_from_header(manager: usize) -> Option<CompactWeatherRoot> {
        let header = read_bytes(manager.checked_add(WEATHER_MANAGER_REGION_ARRAY_OFF)?, 16)?;
        let begin = read_u64_from_slice(&header, 0)? as usize;
        let size = read_u32_from_slice(&header, 8)?;
        let cap = read_u32_from_slice(&header, 12)?;
        if size != WEATHER_REGION_COUNT || cap != WEATHER_REGION_COUNT {
            return None;
        }
        if !is_map_control_heap_pointer(begin) || begin % 8 != 0 {
            return None;
        }
        Some(CompactWeatherRoot {
            manager,
            region_array: begin,
            region_count: size,
        })
    }

    fn validate_compact_weather_root_rows(module_base: usize, root: CompactWeatherRoot) -> bool {
        let Some(byte_len) = WEATHER_REGION_STRIDE.checked_mul(root.region_count as usize) else {
            return false;
        };
        let Some(bytes) = read_bytes(root.region_array, byte_len) else {
            return false;
        };
        let Some(region_vtable) = module_base.checked_add(WEATHER_REGION_VTABLE_RVA) else {
            return false;
        };
        for index in 0..root.region_count as usize {
            let Some(start) = index.checked_mul(WEATHER_REGION_STRIDE) else {
                return false;
            };
            let Some(end) = start.checked_add(WEATHER_REGION_STRIDE) else {
                return false;
            };
            let Some(body) = bytes.get(start..end) else {
                return false;
            };
            if read_u64_from_slice(body, 0).map(|value| value as usize) != Some(region_vtable) {
                return false;
            }
            if read_u32_from_slice(body, WEATHER_REGION_ID_OFF) != Some(index as u32) {
                return false;
            }
        }
        true
    }

    fn read_compact_weather_region_row(
        module_base: usize,
        body: &[u8],
        expected_region_id: u32,
    ) -> Result<CompactWeatherRegionRow, &'static str> {
        let region_vtable = module_base
            .checked_add(WEATHER_REGION_VTABLE_RVA)
            .ok_or("weather_region_vtable_overflow")?;
        if read_u64_from_slice(body, 0).map(|value| value as usize) != Some(region_vtable) {
            return Err("weather_region_vtable");
        }
        let region_id =
            read_u32_from_slice(body, WEATHER_REGION_ID_OFF).ok_or("weather_region_id")?;
        if region_id != expected_region_id {
            return Err("weather_region_id_mismatch");
        }
        let phenomenon = read_u32_from_slice(body, WEATHER_REGION_PHENOM_ENUM_OFF)
            .ok_or("weather_phenomenon")?;
        if phenomenon > 16 {
            return Err("weather_phenomenon_bounds");
        }
        let active_signal = compact_weather_region_active_signal(body)?;
        if (phenomenon >= 1) != active_signal {
            return Err("weather_active_signal_mismatch");
        }
        let rain_light = weather_bool_byte(body, WEATHER_REGION_RAIN_LIGHT_OFF)?;
        let rain_heavy = weather_bool_byte(body, WEATHER_REGION_RAIN_HEAVY_OFF)?;
        let snow = weather_bool_byte(body, WEATHER_REGION_SNOW_OFF)?;
        let blizzard = weather_bool_byte(body, WEATHER_REGION_BLIZZARD_OFF)?;
        let arctic_water = weather_bool_byte(body, WEATHER_REGION_ARCTIC_WATER_OFF)?;
        let active_modifier_count =
            compact_weather_vec_count(body, WEATHER_REGION_ACTIVE_MODS_OFF)?;
        let temperature_raw = read_i32_from_slice(body, WEATHER_REGION_TEMPERATURE_OFF)
            .ok_or("weather_temperature")?;
        if !(-10_000_000..=10_000_000).contains(&temperature_raw) {
            return Err("weather_temperature_bounds");
        }
        let next_weather_change_raw = read_u32_from_slice(body, WEATHER_REGION_NEXT_CHANGE_OFF)
            .ok_or("weather_next_change")?;
        let intensity = body
            .get(WEATHER_REGION_INTENSITY_OFF)
            .copied()
            .ok_or("weather_intensity")? as u32;
        let mut flags = 0u32;
        if rain_light {
            flags |= 1;
        }
        if rain_heavy {
            flags |= 1 << 1;
        }
        if snow {
            flags |= 1 << 2;
        }
        if blizzard {
            flags |= 1 << 3;
        }
        if arctic_water {
            flags |= 1 << 4;
        }
        if active_signal {
            flags |= 1 << 5;
        }
        if phenomenon >= 1 {
            flags |= 1 << 6;
        }
        Ok(CompactWeatherRegionRow {
            region_id,
            flags,
            temperature_raw,
            phenomenon,
            next_weather_change_raw,
            active_modifier_count,
            intensity,
        })
    }

    fn compact_weather_region_active_signal(body: &[u8]) -> Result<bool, &'static str> {
        let begin58 = read_u64_from_slice(body, 0x58).ok_or("weather_active_vec58")? as usize;
        let begin70 = read_u64_from_slice(body, 0x70).ok_or("weather_active_vec70")? as usize;
        Ok(is_map_control_heap_pointer(begin58) || is_map_control_heap_pointer(begin70))
    }

    fn compact_weather_vec_count(body: &[u8], off: usize) -> Result<u32, &'static str> {
        let begin = read_u64_from_slice(body, off).ok_or("weather_vec_begin")? as usize;
        let size = read_u32_from_slice(body, off + 8).ok_or("weather_vec_size")?;
        let cap = read_u32_from_slice(body, off + 12).ok_or("weather_vec_cap")?;
        if size == 0 {
            return Ok(0);
        }
        if !is_map_control_heap_pointer(begin) || cap < size || cap > 4096 {
            return Err("weather_vec_invalid");
        }
        Ok(size)
    }

    fn weather_bool_byte(body: &[u8], off: usize) -> Result<bool, &'static str> {
        match body.get(off).copied() {
            Some(0) => Ok(false),
            Some(1) => Ok(true),
            Some(_) => Err("weather_bool_byte_bounds"),
            None => Err("weather_bool_byte_missing"),
        }
    }

    fn sample_compact_map_detail_with_retry(
        state: &CollectorState,
        include_resources: bool,
        include_buildings: bool,
        tracker: &mut CompactMapDetailTracker,
        attempts: usize,
    ) -> Result<
        (
            Vec<CompactMapDetailStateRow>,
            Vec<CompactMapDetailProvinceRow>,
            bool,
        ),
        &'static str,
    > {
        let attempt_count = attempts.max(1);
        for attempt in 0..attempt_count {
            match sample_compact_map_detail_cached(
                state,
                include_resources,
                include_buildings,
                tracker,
            ) {
                Ok(rows) => return Ok(rows),
                Err(err) if attempt + 1 == attempt_count => return Err(err),
                Err(_) => thread::yield_now(),
            }
        }
        Err("map_detail_retry_exhausted")
    }

    fn sample_compact_map_detail_cached(
        state: &CollectorState,
        include_resources: bool,
        include_buildings: bool,
        tracker: &mut CompactMapDetailTracker,
    ) -> Result<
        (
            Vec<CompactMapDetailStateRow>,
            Vec<CompactMapDetailProvinceRow>,
            bool,
        ),
        &'static str,
    > {
        if !include_resources && !include_buildings {
            return Err("map_detail_empty_selection");
        }
        let cached_result = tracker.topology.as_ref().and_then(|topology| {
            cprovince_array_still_current(state, topology.province_array, topology.province_count)
                .then(|| {
                    sample_compact_map_detail_from_topology(
                        state,
                        topology,
                        include_resources,
                        include_buildings,
                    )
                })
        });
        if let Some(Ok((state_rows, province_rows))) = cached_result {
            return Ok((state_rows, province_rows, false));
        }

        tracker.topology = None;
        let (topology, _, _) = build_compact_map_control_topology(state)?;
        let (state_rows, province_rows) = sample_compact_map_detail_from_topology(
            state,
            &topology,
            include_resources,
            include_buildings,
        )?;
        tracker.topology = Some(topology);
        Ok((state_rows, province_rows, true))
    }

    fn sample_compact_map_detail_from_topology(
        state: &CollectorState,
        topology: &CompactMapControlTopology,
        include_resources: bool,
        include_buildings: bool,
    ) -> Result<
        (
            Vec<CompactMapDetailStateRow>,
            Vec<CompactMapDetailProvinceRow>,
        ),
        &'static str,
    > {
        let mut state_rows = Vec::with_capacity(topology.states.len());
        for root in &topology.states {
            let resources = if include_resources {
                Some(
                    state_resource_entries(root.state_ptr)
                        .ok_or("map_detail_state_resources_unavailable")?,
                )
            } else {
                None
            };
            let buildings = if include_buildings {
                Some(
                    building_level_entries(state.base, root.state_ptr, STATE_OFF_BUILDINGS_VEC)
                        .ok_or("map_detail_state_buildings_unavailable")?,
                )
            } else {
                None
            };
            state_rows.push(CompactMapDetailStateRow {
                state_id: root.state_id,
                resources,
                buildings,
            });
        }

        let mut province_rows = Vec::new();
        if include_buildings {
            province_rows =
                sample_compact_map_detail_province_rows(state.base, &topology.provinces)?;
            if province_rows.len() < MIN_USABLE_PROVINCE_ROWS {
                return Err("map_detail_insufficient_provinces");
            }
        }

        if state_rows.len() < MIN_USABLE_STATE_ROWS {
            return Err("map_detail_insufficient_states");
        }
        Ok((state_rows, province_rows))
    }

    fn sample_compact_map_detail_province_rows(
        module_base: usize,
        roots: &[CompactMapProvinceRoot],
    ) -> Result<Vec<CompactMapDetailProvinceRow>, &'static str> {
        let worker_count = compact_map_detail_sample_worker_count(roots.len());
        if worker_count <= 1 {
            return sample_compact_map_detail_province_rows_serial(module_base, roots);
        }
        let chunk_len = (roots.len() + worker_count - 1) / worker_count;
        let mut rows = Vec::with_capacity(roots.len());
        let mut failed = false;
        thread::scope(|scope| {
            let mut handles = Vec::new();
            for chunk in roots.chunks(chunk_len) {
                handles.push(scope.spawn(move || {
                    sample_compact_map_detail_province_rows_serial(module_base, chunk)
                }));
            }
            for handle in handles {
                match handle.join() {
                    Ok(Ok(mut chunk_rows)) => rows.append(&mut chunk_rows),
                    _ => failed = true,
                }
            }
        });
        if failed {
            Err("map_detail_province_worker_failed")
        } else {
            Ok(rows)
        }
    }

    fn compact_map_detail_sample_worker_count(root_count: usize) -> usize {
        if root_count < COMPACT_MAP_DETAIL_SAMPLE_MIN_ROWS.saturating_mul(2) {
            return 1;
        }
        let target_shards = (root_count + COMPACT_MAP_DETAIL_SAMPLE_MIN_ROWS - 1)
            / COMPACT_MAP_DETAIL_SAMPLE_MIN_ROWS;
        let available = thread::available_parallelism()
            .map(|parallelism| parallelism.get())
            .unwrap_or(1);
        target_shards
            .min(available)
            .min(COMPACT_MAP_DETAIL_SAMPLE_MAX_WORKERS)
            .max(1)
    }

    fn sample_compact_map_detail_province_rows_serial(
        module_base: usize,
        roots: &[CompactMapProvinceRoot],
    ) -> Result<Vec<CompactMapDetailProvinceRow>, &'static str> {
        let mut rows = Vec::with_capacity(roots.len());
        for root in roots {
            let buildings = Some(
                building_level_entries(module_base, root.province_ptr, CPROVINCE_OFF_BUILDINGS_VEC)
                    .ok_or("map_detail_province_buildings_unavailable")?,
            );
            rows.push(CompactMapDetailProvinceRow {
                province_id: root.province_id,
                state_id: root.state_id,
                buildings,
            });
        }
        Ok(rows)
    }

    fn sample_compact_map_control_with_retry(
        state: &CollectorState,
        tracker: &mut CompactMapControlTracker,
        attempts: usize,
    ) -> Result<(Vec<CompactMapStateRow>, Vec<CompactMapProvinceRow>, bool), &'static str> {
        let attempt_count = attempts.max(1);
        for attempt in 0..attempt_count {
            match sample_compact_map_control_cached(state, tracker) {
                Ok(rows) => return Ok(rows),
                Err(err) if attempt + 1 == attempt_count => return Err(err),
                Err(_) => thread::yield_now(),
            }
        }
        Err("map_control_retry_exhausted")
    }

    fn sample_compact_map_control_cached(
        state: &CollectorState,
        tracker: &mut CompactMapControlTracker,
    ) -> Result<(Vec<CompactMapStateRow>, Vec<CompactMapProvinceRow>, bool), &'static str> {
        let cached_result = tracker.topology.as_ref().and_then(|topology| {
            cprovince_array_still_current(state, topology.province_array, topology.province_count)
                .then(|| sample_compact_map_control_from_topology(topology))
        });
        if let Some(Ok((state_rows, province_rows))) = cached_result {
            return Ok((state_rows, province_rows, false));
        }

        tracker.topology = None;
        let (topology, state_rows, province_rows) = build_compact_map_control_topology(state)?;
        tracker.topology = Some(topology);
        Ok((state_rows, province_rows, true))
    }

    fn sample_compact_map_control_from_topology(
        topology: &CompactMapControlTopology,
    ) -> Result<(Vec<CompactMapStateRow>, Vec<CompactMapProvinceRow>), &'static str> {
        let mut state_rows = Vec::with_capacity(topology.states.len());
        for root in &topology.states {
            let owner_tag_db_id = read_u32(
                root.state_ptr
                    .checked_add(STATE_OFF_OWNER)
                    .ok_or("state_owner_overflow")?,
            )
            .ok_or("state_owner_unreadable")?;
            let controller_tag_db_id = read_u32(
                root.state_ptr
                    .checked_add(STATE_OFF_CTRL)
                    .ok_or("state_ctrl_overflow")?,
            )
            .ok_or("state_ctrl_unreadable")?;
            if owner_tag_db_id > 1024 || controller_tag_db_id > 1024 {
                return Err("state_tag_db_id_invalid");
            }
            state_rows.push(CompactMapStateRow {
                state_id: root.state_id,
                owner_tag_db_id,
                controller_tag_db_id,
            });
        }

        let mut province_rows = Vec::with_capacity(topology.provinces.len());
        for root in &topology.provinces {
            let controller_tag_db_id = read_u32(
                root.province_ptr
                    .checked_add(CPROVINCE_OFF_CONTROLLER)
                    .ok_or("controller_overflow")?,
            )
            .ok_or("controller_unreadable")?;
            if controller_tag_db_id > 1024 {
                return Err("controller_tag_db_id_invalid");
            }
            province_rows.push(CompactMapProvinceRow {
                province_id: root.province_id,
                controller_tag_db_id,
                state_id: root.state_id,
            });
        }

        Ok((state_rows, province_rows))
    }

    fn build_compact_map_control_topology(
        state: &CollectorState,
    ) -> Result<
        (
            CompactMapControlTopology,
            Vec<CompactMapStateRow>,
            Vec<CompactMapProvinceRow>,
        ),
        &'static str,
    > {
        let (province_array, province_count, province_ptrs) =
            cprovince_array_snapshot(state).ok_or("province_array_unavailable")?;
        let cprovince_vtable = state
            .base
            .checked_add(CPROVINCE_VTABLE_RVA)
            .ok_or("profile_mismatch")?;
        let state_vtable = state
            .base
            .checked_add(STATE_VTABLE_RVA)
            .ok_or("profile_mismatch")?;
        let mut state_ptrs: BTreeMap<u32, usize> = BTreeMap::new();
        let mut province_roots = Vec::with_capacity(province_count.saturating_sub(1) as usize);
        let mut province_rows = Vec::with_capacity(province_count.saturating_sub(1) as usize);

        for province_id in 1..province_count {
            let province_ptr = cprovince_ptr_from_snapshot(&province_ptrs, province_id)
                .ok_or("province_pointer_unavailable")?;
            if province_ptr == 0 {
                continue;
            }
            if !is_map_control_heap_pointer(province_ptr) {
                return Err("province_pointer_invalid");
            }
            if read_u64(province_ptr).map(|value| value as usize) != Some(cprovince_vtable) {
                return Err("province_vtable_mismatch");
            }
            if read_u32(
                province_ptr
                    .checked_add(CPROVINCE_OFF_ID)
                    .ok_or("province_id_overflow")?,
            ) != Some(province_id)
            {
                return Err("province_id_mismatch");
            }

            let state_ptr = read_u64(
                province_ptr
                    .checked_add(CPROVINCE_OFF_STATE)
                    .ok_or("state_overflow")?,
            )
            .ok_or("state_pointer_unreadable")? as usize;
            let state_id = if state_ptr == 0 {
                0
            } else {
                if !is_map_control_heap_pointer(state_ptr) {
                    return Err("state_pointer_invalid");
                }
                if read_u64(state_ptr).map(|value| value as usize) != Some(state_vtable) {
                    return Err("state_vtable_mismatch");
                }
                let state_id = read_u32(
                    state_ptr
                        .checked_add(STATE_OFF_SID)
                        .ok_or("state_id_overflow")?,
                )
                .ok_or("state_id_unreadable")?;
                if state_id == 0 || state_id > MAX_MAP_CONTROL_STATE_ID {
                    return Err("state_id_invalid");
                }
                if let Some(previous) = state_ptrs.insert(state_id, state_ptr) {
                    if previous != state_ptr {
                        return Err("state_pointer_conflict");
                    }
                }
                state_id
            };
            let controller_tag_db_id = read_u32(
                province_ptr
                    .checked_add(CPROVINCE_OFF_CONTROLLER)
                    .ok_or("controller_overflow")?,
            )
            .ok_or("controller_unreadable")?;
            if controller_tag_db_id > 1024 {
                return Err("controller_tag_db_id_invalid");
            }
            province_roots.push(CompactMapProvinceRoot {
                province_id,
                province_ptr,
                state_id,
            });
            province_rows.push(CompactMapProvinceRow {
                province_id,
                controller_tag_db_id,
                state_id,
            });
        }

        if state_ptrs.len() < MIN_USABLE_STATE_ROWS
            || province_rows.len() < MIN_USABLE_PROVINCE_ROWS
        {
            return Err("insufficient_map_rows");
        }

        let mut state_roots = Vec::with_capacity(state_ptrs.len());
        let mut state_rows = Vec::with_capacity(state_ptrs.len());
        for (state_id, state_ptr) in state_ptrs {
            if read_u64(state_ptr).map(|value| value as usize) != Some(state_vtable) {
                return Err("state_vtable_changed");
            }
            if read_u32(
                state_ptr
                    .checked_add(STATE_OFF_SID)
                    .ok_or("state_sid_overflow")?,
            ) != Some(state_id)
            {
                return Err("state_id_changed");
            }
            let owner_tag_db_id = read_u32(
                state_ptr
                    .checked_add(STATE_OFF_OWNER)
                    .ok_or("state_owner_overflow")?,
            )
            .ok_or("state_owner_unreadable")?;
            let controller_tag_db_id = read_u32(
                state_ptr
                    .checked_add(STATE_OFF_CTRL)
                    .ok_or("state_ctrl_overflow")?,
            )
            .ok_or("state_ctrl_unreadable")?;
            if owner_tag_db_id > 1024 || controller_tag_db_id > 1024 {
                return Err("state_tag_db_id_invalid");
            }
            state_roots.push(CompactMapStateRoot {
                state_id,
                state_ptr,
            });
            state_rows.push(CompactMapStateRow {
                state_id,
                owner_tag_db_id,
                controller_tag_db_id,
            });
        }

        if !cprovince_array_still_current(state, province_array, province_count) {
            return Err("province_array_changed");
        }
        Ok((
            CompactMapControlTopology {
                province_array,
                province_count,
                states: state_roots,
                provinces: province_roots,
            },
            state_rows,
            province_rows,
        ))
    }

    fn read_compact_country_domain_bundle(
        state: &CollectorState,
        control: &CollectorControl,
        specs: Vec<CompactCountryDomainSpec>,
        status_flags: u32,
        tracker: &mut CompactCountryFrameTracker,
    ) -> CompactBundleRead {
        let read_started = Instant::now();
        let include_fuel = specs
            .iter()
            .any(|spec| matches!(spec.kind, CompactCountryDomainKind::Fuel));
        let include_production = specs
            .iter()
            .any(|spec| matches!(spec.kind, CompactCountryDomainKind::Production));
        let include_focus = specs
            .iter()
            .any(|spec| matches!(spec.kind, CompactCountryDomainKind::Focus));
        let include_tech = specs
            .iter()
            .any(|spec| matches!(spec.kind, CompactCountryDomainKind::Tech));
        let include_politics = specs
            .iter()
            .any(|spec| matches!(spec.kind, CompactCountryDomainKind::Politics));
        let include_politics_residuals = specs
            .iter()
            .any(|spec| matches!(spec.kind, CompactCountryDomainKind::PoliticsResiduals));
        let include_decisions = specs
            .iter()
            .any(|spec| matches!(spec.kind, CompactCountryDomainKind::Decisions));
        let include_diplomacy = specs
            .iter()
            .any(|spec| matches!(spec.kind, CompactCountryDomainKind::Diplomacy));
        let mut read_status_flags = status_flags;
        let mut rows = if state.daily_match
            && state.long_string_match
            && state.country_identity.has_scalar_source()
            && !specs.is_empty()
        {
            if compact_bundle_is_politics_only(&specs) {
                let (rows, worker_panic) = state.country_identity.current_politics_rows_sharded(
                    state.country_database_ptr as usize,
                    Some(&control.idea_group_filter),
                    tracker,
                );
                if worker_panic {
                    read_status_flags |= COMPACT_STATUS_WORKER_PANIC;
                }
                rows
            } else {
                state.country_identity.current_rows(
                    state.country_database_ptr as usize,
                    true,
                    include_fuel,
                    include_production,
                    include_focus,
                    include_tech,
                    include_politics,
                    include_politics_residuals,
                    include_decisions,
                    include_diplomacy,
                    Some(&control.advisor_token_filter),
                    Some(&control.tech_def_filter),
                    Some(&control.idea_group_filter),
                    Some(&mut *tracker),
                )
            }
        } else {
            Vec::new()
        };
        if include_diplomacy {
            let tag_table = country_tag_table(state.country_database_ptr as usize);
            if let (Some(tag_table), true) = (tag_table, control.war_relation_bridge_valid) {
                if war_relation_bridge_well_formed(&control.war_relation_bridge) {
                    if let Some(war_relations) =
                        read_war_relation_rows(state.base, tag_table, &control.war_relation_bridge)
                    {
                        apply_war_relations_to_country_rows(&mut rows, &war_relations);
                        read_status_flags |= COMPACT_STATUS_WAR_BRIDGE_APPLIED;
                    }
                }
            }
        }
        mark_compact_rows_seen(tracker, &rows);
        CompactBundleRead {
            specs,
            rows,
            read_time_us: duration_micros_u64(read_started.elapsed()),
            row_count: state.country_identity.rows.len().min(u32::MAX as usize) as u32,
            status_flags: read_status_flags,
        }
    }

