    fn compact_fuel_data_payload(
        rows: &[CountryObjectRow],
        elapsed_wall_ms: u64,
        status_flags: u32,
    ) -> Vec<u8> {
        let fuel_row_count = rows.iter().filter(|row| row.fuel.is_some()).count();
        let mut payload = Vec::with_capacity(24usize.saturating_add(fuel_row_count * 40));
        let packed_row_count = fuel_row_count.min(u32::MAX as usize) as u32;
        payload.extend_from_slice(&elapsed_wall_ms.to_le_bytes());
        payload.extend_from_slice(&packed_row_count.to_le_bytes());
        payload.extend_from_slice(&packed_row_count.to_le_bytes());
        payload.extend_from_slice(&status_flags.to_le_bytes());
        payload.extend_from_slice(&FUEL_SCALE_RAW.to_le_bytes());
        for row in rows.iter().filter(|row| row.fuel.is_some()) {
            let fuel = row.fuel.expect("filtered fuel row");
            payload.extend_from_slice(&row.tag_db_id.to_le_bytes());
            payload.extend_from_slice(&1u32.to_le_bytes());
            payload.extend_from_slice(&fuel.current_raw.to_le_bytes());
            payload.extend_from_slice(&fuel.max_raw.to_le_bytes());
            payload.extend_from_slice(&fuel.gain_raw.to_le_bytes());
            payload.extend_from_slice(&fuel.cost_raw.to_le_bytes());
        }
        payload
    }

    fn compact_production_data_payload(
        rows: &[CountryObjectRow],
        elapsed_wall_ms: u64,
        status_flags: u32,
    ) -> Vec<u8> {
        let mut country_count = 0usize;
        let mut stockpile_count = 0usize;
        let mut military_count = 0usize;
        let mut naval_count = 0usize;
        let mut construction_count = 0usize;
        for production in rows.iter().filter_map(|row| row.production.as_ref()) {
            country_count += 1;
            stockpile_count += production.stockpile.as_ref().map(Vec::len).unwrap_or(0);
            military_count += production
                .military_lines
                .as_ref()
                .map(Vec::len)
                .unwrap_or(0);
            naval_count += production.naval_lines.as_ref().map(Vec::len).unwrap_or(0);
            construction_count += production
                .construction_queue
                .as_ref()
                .map(Vec::len)
                .unwrap_or(0);
        }
        let mut payload = Vec::with_capacity(
            40usize
                .saturating_add(stockpile_count * 16)
                .saturating_add(military_count.saturating_add(naval_count) * 32)
                .saturating_add(construction_count * 32),
        );
        let packed_country_count = country_count.min(u32::MAX as usize) as u32;
        payload.extend_from_slice(&elapsed_wall_ms.to_le_bytes());
        payload.extend_from_slice(&packed_country_count.to_le_bytes());
        payload.extend_from_slice(&packed_country_count.to_le_bytes());
        payload.extend_from_slice(&status_flags.to_le_bytes());
        payload.extend_from_slice(&COMPACT_PRODUCTION_SCALE_RAW.to_le_bytes());
        payload.extend_from_slice(&(stockpile_count.min(u32::MAX as usize) as u32).to_le_bytes());
        payload.extend_from_slice(&(military_count.min(u32::MAX as usize) as u32).to_le_bytes());
        payload.extend_from_slice(&(naval_count.min(u32::MAX as usize) as u32).to_le_bytes());
        payload
            .extend_from_slice(&(construction_count.min(u32::MAX as usize) as u32).to_le_bytes());

        for row in rows.iter().filter(|row| row.production.is_some()) {
            let production = row.production.as_ref().expect("filtered production row");
            if let Some(stockpile) = production.stockpile.as_ref() {
                for stock in stockpile {
                    payload.extend_from_slice(&row.tag_db_id.to_le_bytes());
                    payload.extend_from_slice(&stock.variant_id.to_le_bytes());
                    payload.extend_from_slice(
                        &compact_scaled_i64(stock.amount, COMPACT_PRODUCTION_SCALE_RAW as f64)
                            .unwrap_or(0)
                            .to_le_bytes(),
                    );
                }
            }
        }
        for (tag_db_id, line_kind, lines) in rows.iter().filter_map(|row| {
            row.production
                .as_ref()
                .and_then(|production| production.military_lines.as_ref())
                .map(|lines| (row.tag_db_id, 1u32, lines))
        }) {
            append_compact_production_lines(&mut payload, tag_db_id, line_kind, lines);
        }
        for (tag_db_id, line_kind, lines) in rows.iter().filter_map(|row| {
            row.production
                .as_ref()
                .and_then(|production| production.naval_lines.as_ref())
                .map(|lines| (row.tag_db_id, 2u32, lines))
        }) {
            append_compact_production_lines(&mut payload, tag_db_id, line_kind, lines);
        }
        for row in rows.iter().filter(|row| row.production.is_some()) {
            let production = row.production.as_ref().expect("filtered production row");
            if let Some(construction_queue) = production.construction_queue.as_ref() {
                for construction in construction_queue {
                    payload.extend_from_slice(&row.tag_db_id.to_le_bytes());
                    payload.extend_from_slice(&construction.id.to_le_bytes());
                    payload.extend_from_slice(
                        &construction.template_id.unwrap_or(u32::MAX).to_le_bytes(),
                    );
                    payload.extend_from_slice(&construction.active_factories.to_le_bytes());
                    payload.extend_from_slice(
                        &compact_scaled_i32(construction.cost, COMPACT_PRODUCTION_SCALE_RAW as f64)
                            .unwrap_or(0)
                            .to_le_bytes(),
                    );
                    payload.extend_from_slice(
                        &compact_scaled_i32(
                            construction.produced,
                            COMPACT_PRODUCTION_SCALE_RAW as f64,
                        )
                        .unwrap_or(0)
                        .to_le_bytes(),
                    );
                    payload.extend_from_slice(&construction.priority.to_le_bytes());
                    payload.extend_from_slice(&0u32.to_le_bytes());
                }
            }
        }
        payload
    }

    fn append_compact_production_lines(
        payload: &mut Vec<u8>,
        tag_db_id: u32,
        kind: u32,
        lines: &[CountryProductionLineRow],
    ) {
        for line in lines {
            payload.extend_from_slice(&tag_db_id.to_le_bytes());
            payload.extend_from_slice(&kind.to_le_bytes());
            payload.extend_from_slice(&line.id.to_le_bytes());
            payload.extend_from_slice(&line.active_factories.to_le_bytes());
            payload.extend_from_slice(
                &compact_scaled_i32(line.cost, COMPACT_PRODUCTION_SCALE_RAW as f64)
                    .unwrap_or(0)
                    .to_le_bytes(),
            );
            payload.extend_from_slice(
                &compact_scaled_i32(line.speed, COMPACT_PRODUCTION_SCALE_RAW as f64)
                    .unwrap_or(0)
                    .to_le_bytes(),
            );
            payload.extend_from_slice(
                &compact_scaled_i32(line.produced, COMPACT_PRODUCTION_SCALE_RAW as f64)
                    .unwrap_or(0)
                    .to_le_bytes(),
            );
            payload.extend_from_slice(&line.amount.to_le_bytes());
        }
    }

    fn compact_focus_data_payload(
        rows: &[CountryObjectRow],
        elapsed_wall_ms: u64,
        status_flags: u32,
    ) -> Vec<u8> {
        let country_count = rows.iter().filter(|row| row.focus.is_some()).count();
        let completed_token_count = rows
            .iter()
            .filter_map(|row| row.focus.as_ref())
            .filter_map(|focus| focus.completed.as_ref())
            .map(Vec::len)
            .sum::<usize>();
        let packed_country_count = country_count.min(u32::MAX as usize) as u32;
        let mut payload = Vec::new();
        payload.extend_from_slice(&elapsed_wall_ms.to_le_bytes());
        payload.extend_from_slice(&packed_country_count.to_le_bytes());
        payload.extend_from_slice(&packed_country_count.to_le_bytes());
        payload.extend_from_slice(&status_flags.to_le_bytes());
        payload.extend_from_slice(&COMPACT_FIXED_SCALE_RAW.to_le_bytes());
        payload.extend_from_slice(
            &(completed_token_count.min(u32::MAX as usize) as u32).to_le_bytes(),
        );
        for row in rows.iter().filter(|row| row.focus.is_some()) {
            let focus = row.focus.as_ref().expect("filtered focus row");
            let progress_raw = focus
                .progress
                .and_then(|progress| compact_scaled_i32(progress, COMPACT_FIXED_SCALE_RAW as f64));
            let mut flags = 0u32;
            if focus.focus_tree.is_some() {
                flags |= 1;
            }
            if focus.completed_count.is_some() {
                flags |= 1 << 1;
            }
            if focus.current.is_some() {
                flags |= 1 << 2;
            }
            if focus.current_continuous.is_some() {
                flags |= 1 << 3;
            }
            if progress_raw.is_some() {
                flags |= 1 << 4;
            }
            if focus.completed.is_some() {
                flags |= 1 << 5;
            }
            payload.extend_from_slice(&row.tag_db_id.to_le_bytes());
            payload.extend_from_slice(&flags.to_le_bytes());
            payload.extend_from_slice(&focus.completed_count.unwrap_or(u32::MAX).to_le_bytes());
            payload.extend_from_slice(&progress_raw.unwrap_or(0).to_le_bytes());
            append_compact_string(&mut payload, focus.focus_tree.as_deref());
            append_compact_string(&mut payload, focus.current.as_deref());
            append_compact_string(&mut payload, focus.current_continuous.as_deref());
        }
        for row in rows.iter().filter(|row| row.focus.is_some()) {
            let focus = row.focus.as_ref().expect("filtered focus row");
            if let Some(completed) = focus.completed.as_ref() {
                for token in completed {
                    payload.extend_from_slice(&row.tag_db_id.to_le_bytes());
                    append_compact_string(&mut payload, Some(token));
                }
            }
        }
        payload
    }

    fn compact_tech_data_payload(
        rows: &[CountryObjectRow],
        elapsed_wall_ms: u64,
        status_flags: u32,
    ) -> Vec<u8> {
        let mut country_count = 0usize;
        let mut active_count = 0usize;
        for row in rows.iter().filter(|row| row.research.is_some()) {
            country_count += 1;
            active_count += row
                .research
                .as_ref()
                .and_then(|research| research.active_research.as_ref())
                .map(Vec::len)
                .unwrap_or(0);
        }
        let mut payload = Vec::with_capacity(
            32usize
                .saturating_add(country_count * 16)
                .saturating_add(active_count * 40),
        );
        let packed_country_count = country_count.min(u32::MAX as usize) as u32;
        payload.extend_from_slice(&elapsed_wall_ms.to_le_bytes());
        payload.extend_from_slice(&packed_country_count.to_le_bytes());
        payload.extend_from_slice(&packed_country_count.to_le_bytes());
        payload.extend_from_slice(&status_flags.to_le_bytes());
        payload.extend_from_slice(&TECH_PROGRESS_SCALE_RAW.to_le_bytes());
        payload.extend_from_slice(&TECH_LIVE_PROGRESS_SCALE_RAW.to_le_bytes());
        payload.extend_from_slice(&(active_count.min(u32::MAX as usize) as u32).to_le_bytes());
        for row in rows.iter().filter(|row| row.research.is_some()) {
            let research = row.research.as_ref().expect("filtered research row");
            let mut flags = 0u32;
            if research.completed_tech_count.is_some() {
                flags |= 1;
            }
            if research.research_slot_count.is_some() {
                flags |= 1 << 1;
            }
            if research.active_research.is_some() {
                flags |= 1 << 2;
            }
            payload.extend_from_slice(&row.tag_db_id.to_le_bytes());
            payload.extend_from_slice(&flags.to_le_bytes());
            payload.extend_from_slice(
                &research
                    .completed_tech_count
                    .unwrap_or(u32::MAX)
                    .to_le_bytes(),
            );
            payload.extend_from_slice(
                &research
                    .research_slot_count
                    .unwrap_or(u32::MAX)
                    .to_le_bytes(),
            );
        }
        for row in rows.iter().filter(|row| row.research.is_some()) {
            let research = row.research.as_ref().expect("filtered research row");
            if let Some(active) = research.active_research.as_ref() {
                for slot in active {
                    let mut flags = 0u32;
                    if slot.live_progress_raw.is_some() {
                        flags |= 1;
                    }
                    if slot.base_required_points_raw.is_some() {
                        flags |= 1 << 1;
                    }
                    payload.extend_from_slice(&row.tag_db_id.to_le_bytes());
                    payload.extend_from_slice(&slot.slot_index.to_le_bytes());
                    payload.extend_from_slice(&slot.tech_handle_raw.to_le_bytes());
                    payload.extend_from_slice(&slot.tech_def_index_raw.to_le_bytes());
                    payload.extend_from_slice(&slot.progress_raw.to_le_bytes());
                    payload.extend_from_slice(&flags.to_le_bytes());
                    payload.extend_from_slice(&slot.live_progress_raw.unwrap_or(0).to_le_bytes());
                    payload.extend_from_slice(
                        &slot.base_required_points_raw.unwrap_or(0).to_le_bytes(),
                    );
                }
            }
        }
        payload
    }

    fn compact_politics_data_payload(
        rows: &[CountryObjectRow],
        elapsed_wall_ms: u64,
        status_flags: u32,
    ) -> Vec<u8> {
        let mut country_count = 0usize;
        let mut popularity_count = 0usize;
        let mut law_count = 0usize;
        let mut advisor_token_count = 0usize;
        let mut national_spirit_count = 0usize;
        for politics in rows.iter().filter_map(|row| row.politics.as_ref()) {
            country_count += 1;
            popularity_count += politics
                .popularities
                .as_ref()
                .map(BTreeMap::len)
                .unwrap_or(0);
            law_count += politics.laws.as_ref().map(BTreeMap::len).unwrap_or(0);
            advisor_token_count += politics
                .advisor_ideas
                .as_ref()
                .map(|groups| groups.values().map(Vec::len).sum::<usize>())
                .unwrap_or(0);
            national_spirit_count += politics
                .national_spirits
                .as_ref()
                .map(Vec::len)
                .unwrap_or(0);
        }
        let packed_country_count = country_count.min(u32::MAX as usize) as u32;
        let mut payload = Vec::new();
        payload.extend_from_slice(&elapsed_wall_ms.to_le_bytes());
        payload.extend_from_slice(&packed_country_count.to_le_bytes());
        payload.extend_from_slice(&packed_country_count.to_le_bytes());
        payload.extend_from_slice(&status_flags.to_le_bytes());
        payload.extend_from_slice(&COMPACT_FIXED_SCALE_RAW.to_le_bytes());
        payload.extend_from_slice(&(popularity_count.min(u32::MAX as usize) as u32).to_le_bytes());
        payload.extend_from_slice(&(law_count.min(u32::MAX as usize) as u32).to_le_bytes());
        payload
            .extend_from_slice(&(advisor_token_count.min(u32::MAX as usize) as u32).to_le_bytes());
        payload.extend_from_slice(
            &(national_spirit_count.min(u32::MAX as usize) as u32).to_le_bytes(),
        );

        for row in rows.iter().filter(|row| row.politics.is_some()) {
            let politics = row.politics.as_ref().expect("filtered politics row");
            let mut flags = 0u32;
            if politics.popularities.is_some() {
                flags |= 1;
            }
            if politics.ruling_party.is_some() {
                flags |= 1 << 1;
            }
            if politics.leader.is_some() {
                flags |= 1 << 2;
            }
            if politics.laws.is_some() {
                flags |= 1 << 3;
            }
            if politics.advisor_ideas.is_some() {
                flags |= 1 << 4;
            }
            if politics.national_spirits.is_some() {
                flags |= 1 << 5;
            }
            if politics.idea_count.is_some() {
                flags |= 1 << 6;
            }
            if politics.election_frequency.is_some() {
                flags |= 1 << 7;
            }
            if politics.party_count.is_some() {
                flags |= 1 << 8;
            }
            if politics.low_confidence.is_some() {
                flags |= 1 << 9;
            }
            payload.extend_from_slice(&row.tag_db_id.to_le_bytes());
            payload.extend_from_slice(&flags.to_le_bytes());
            payload.extend_from_slice(&politics.idea_count.unwrap_or(u32::MAX).to_le_bytes());
            payload.extend_from_slice(
                &politics
                    .election_frequency
                    .unwrap_or(u32::MAX)
                    .to_le_bytes(),
            );
            payload.extend_from_slice(&politics.party_count.unwrap_or(u32::MAX).to_le_bytes());
            let low_confidence = match politics.low_confidence {
                Some(false) => 0u32,
                Some(true) => 1u32,
                None => u32::MAX,
            };
            payload.extend_from_slice(&low_confidence.to_le_bytes());
            payload.extend_from_slice(
                &politics
                    .leader
                    .as_ref()
                    .map(|leader| leader.char_id)
                    .unwrap_or(0)
                    .to_le_bytes(),
            );
            append_compact_string(&mut payload, politics.ruling_party.as_deref());
            append_compact_string(
                &mut payload,
                politics
                    .leader
                    .as_ref()
                    .and_then(|leader| leader.name.as_deref()),
            );
            append_compact_string(
                &mut payload,
                politics
                    .leader
                    .as_ref()
                    .and_then(|leader| leader.token.as_deref()),
            );
            append_compact_string(
                &mut payload,
                politics
                    .leader
                    .as_ref()
                    .and_then(|leader| leader.ideology_group.as_deref()),
            );
        }

        for row in rows.iter().filter(|row| row.politics.is_some()) {
            let politics = row.politics.as_ref().expect("filtered politics row");
            if let Some(popularities) = politics.popularities.as_ref() {
                for (ideology, value) in popularities {
                    payload.extend_from_slice(&row.tag_db_id.to_le_bytes());
                    append_compact_string(&mut payload, Some(ideology));
                    payload.extend_from_slice(
                        &compact_scaled_i32(*value, COMPACT_FIXED_SCALE_RAW as f64)
                            .unwrap_or(0)
                            .to_le_bytes(),
                    );
                }
            }
        }
        for row in rows.iter().filter(|row| row.politics.is_some()) {
            let politics = row.politics.as_ref().expect("filtered politics row");
            if let Some(laws) = politics.laws.as_ref() {
                for (group, token) in laws {
                    payload.extend_from_slice(&row.tag_db_id.to_le_bytes());
                    append_compact_string(&mut payload, Some(group));
                    append_compact_string(&mut payload, Some(token));
                }
            }
        }
        for row in rows.iter().filter(|row| row.politics.is_some()) {
            let politics = row.politics.as_ref().expect("filtered politics row");
            if let Some(advisor_ideas) = politics.advisor_ideas.as_ref() {
                for (group, tokens) in advisor_ideas {
                    for token in tokens {
                        payload.extend_from_slice(&row.tag_db_id.to_le_bytes());
                        append_compact_string(&mut payload, Some(group));
                        append_compact_string(&mut payload, Some(token));
                    }
                }
            }
        }
        for row in rows.iter().filter(|row| row.politics.is_some()) {
            let politics = row.politics.as_ref().expect("filtered politics row");
            if let Some(national_spirits) = politics.national_spirits.as_ref() {
                for token in national_spirits {
                    payload.extend_from_slice(&row.tag_db_id.to_le_bytes());
                    append_compact_string(&mut payload, Some(token));
                }
            }
        }
        payload
    }

    fn compact_politics_residuals_data_payload(
        rows: &[CountryObjectRow],
        elapsed_wall_ms: u64,
        status_flags: u32,
    ) -> Vec<u8> {
        let mut country_count = 0usize;
        let mut advisor_detail_count = 0usize;
        for residuals in rows
            .iter()
            .filter_map(|row| row.politics_residuals.as_ref())
        {
            country_count += 1;
            advisor_detail_count += residuals
                .appointed_advisor_details
                .as_ref()
                .map(Vec::len)
                .unwrap_or(0);
        }
        let packed_country_count = country_count.min(u32::MAX as usize) as u32;
        let mut payload = Vec::new();
        payload.extend_from_slice(&elapsed_wall_ms.to_le_bytes());
        payload.extend_from_slice(&packed_country_count.to_le_bytes());
        payload.extend_from_slice(&packed_country_count.to_le_bytes());
        payload.extend_from_slice(&status_flags.to_le_bytes());
        payload
            .extend_from_slice(&(advisor_detail_count.min(u32::MAX as usize) as u32).to_le_bytes());
        for row in rows.iter().filter(|row| row.politics_residuals.is_some()) {
            let residuals = row
                .politics_residuals
                .as_ref()
                .expect("filtered politics residuals row");
            let mut flags = 0u32;
            if residuals.last_election.is_some() {
                flags |= 1;
            }
            if residuals.elections_allowed.is_some() {
                flags |= 1 << 1;
            }
            if residuals.appointed_advisor_details.is_some() {
                flags |= 1 << 2;
            }
            payload.extend_from_slice(&row.tag_db_id.to_le_bytes());
            payload.extend_from_slice(&flags.to_le_bytes());
            let elections_allowed = match residuals.elections_allowed {
                Some(false) => 0u32,
                Some(true) => 1u32,
                None => u32::MAX,
            };
            payload.extend_from_slice(&elections_allowed.to_le_bytes());
            payload.extend_from_slice(
                &(residuals
                    .appointed_advisor_details
                    .as_ref()
                    .map(Vec::len)
                    .unwrap_or(0)
                    .min(u32::MAX as usize) as u32)
                    .to_le_bytes(),
            );
            append_compact_string(&mut payload, residuals.last_election.as_deref());
        }
        for row in rows.iter().filter(|row| row.politics_residuals.is_some()) {
            let residuals = row
                .politics_residuals
                .as_ref()
                .expect("filtered politics residuals row");
            if let Some(details) = residuals.appointed_advisor_details.as_ref() {
                for detail in details {
                    payload.extend_from_slice(&row.tag_db_id.to_le_bytes());
                    append_compact_string(&mut payload, Some(&detail.idea_token));
                    append_compact_string(&mut payload, detail.slot.as_deref());
                    append_compact_string(&mut payload, detail.ledger.as_deref());
                    append_compact_string(&mut payload, detail.character.as_deref());
                }
            }
        }
        payload
    }

    fn compact_decisions_data_payload(
        rows: &[CountryObjectRow],
        elapsed_wall_ms: u64,
        status_flags: u32,
    ) -> Vec<u8> {
        let mut country_count = 0usize;
        let mut timed_count = 0usize;
        for decisions in rows.iter().filter_map(|row| row.decisions.as_ref()) {
            country_count += 1;
            timed_count += decisions.timed_live.as_ref().map(Vec::len).unwrap_or(0);
        }
        let packed_country_count = country_count.min(u32::MAX as usize) as u32;
        let mut payload = Vec::new();
        payload.extend_from_slice(&elapsed_wall_ms.to_le_bytes());
        payload.extend_from_slice(&packed_country_count.to_le_bytes());
        payload.extend_from_slice(&packed_country_count.to_le_bytes());
        payload.extend_from_slice(&status_flags.to_le_bytes());
        payload.extend_from_slice(&(timed_count.min(u32::MAX as usize) as u32).to_le_bytes());
        for row in rows.iter().filter(|row| row.decisions.is_some()) {
            let decisions = row.decisions.as_ref().expect("filtered decisions row");
            let mut flags = 0u32;
            if decisions.status_present.is_some() {
                flags |= 1;
            }
            if decisions.timed_live.is_some() {
                flags |= 1 << 1;
            }
            payload.extend_from_slice(&row.tag_db_id.to_le_bytes());
            payload.extend_from_slice(&flags.to_le_bytes());
            for key in [
                "active_timed_decision",
                "active_targeted_decision",
                "active_targeted_timed_decision",
                "decisions_taken_bucket",
                "decision_to_re_enable",
            ] {
                payload.extend_from_slice(
                    &decisions
                        .status_present
                        .as_ref()
                        .and_then(|present| present.get(key).copied())
                        .unwrap_or(0)
                        .to_le_bytes(),
                );
            }
            payload.extend_from_slice(
                &(decisions
                    .timed_live
                    .as_ref()
                    .map(Vec::len)
                    .unwrap_or(0)
                    .min(u32::MAX as usize) as u32)
                    .to_le_bytes(),
            );
        }
        for row in rows.iter().filter(|row| row.decisions.is_some()) {
            let decisions = row.decisions.as_ref().expect("filtered decisions row");
            if let Some(timed_live) = decisions.timed_live.as_ref() {
                for timed in timed_live {
                    payload.extend_from_slice(&row.tag_db_id.to_le_bytes());
                    payload.extend_from_slice(&timed.days.to_le_bytes());
                    payload.extend_from_slice(&timed.state.to_le_bytes());
                    append_compact_string(&mut payload, Some(&timed.decision));
                }
            }
        }
        payload
    }

    fn compact_diplomacy_data_payload(
        rows: &[CountryObjectRow],
        elapsed_wall_ms: u64,
        status_flags: u32,
    ) -> Vec<u8> {
        let mut country_count = 0usize;
        let mut relation_count = 0usize;
        for row in rows.iter().filter(|row| row.diplomacy.is_some()) {
            country_count += 1;
            relation_count += row
                .diplomacy
                .as_ref()
                .and_then(|diplomacy| diplomacy.at_war.as_ref())
                .map(Vec::len)
                .unwrap_or(0);
        }
        let mut payload = Vec::with_capacity(
            24usize
                .saturating_add(country_count * 24)
                .saturating_add(relation_count * 16),
        );
        let packed_country_count = country_count.min(u32::MAX as usize) as u32;
        payload.extend_from_slice(&elapsed_wall_ms.to_le_bytes());
        payload.extend_from_slice(&packed_country_count.to_le_bytes());
        payload.extend_from_slice(&packed_country_count.to_le_bytes());
        payload.extend_from_slice(&status_flags.to_le_bytes());
        payload.extend_from_slice(&(relation_count.min(u32::MAX as usize) as u32).to_le_bytes());
        for row in rows.iter().filter(|row| row.diplomacy.is_some()) {
            let diplomacy = row.diplomacy.as_ref().expect("filtered diplomacy row");
            let mut flags = 0u32;
            if diplomacy.at_war.is_some() {
                flags |= 1;
            }
            if diplomacy.casualties.is_some() {
                flags |= 1 << 1;
            }
            payload.extend_from_slice(&row.tag_db_id.to_le_bytes());
            payload.extend_from_slice(&flags.to_le_bytes());
            payload.extend_from_slice(&diplomacy.faction_group.to_le_bytes());
            payload.extend_from_slice(
                &(diplomacy
                    .at_war
                    .as_ref()
                    .map(Vec::len)
                    .unwrap_or(0)
                    .min(u32::MAX as usize) as u32)
                    .to_le_bytes(),
            );
            payload.extend_from_slice(&diplomacy.casualties.unwrap_or(0).to_le_bytes());
        }
        for row in rows.iter().filter(|row| row.diplomacy.is_some()) {
            let diplomacy = row.diplomacy.as_ref().expect("filtered diplomacy row");
            if let Some(at_war) = diplomacy.at_war.as_ref() {
                for tag in at_war {
                    payload.extend_from_slice(&row.tag_db_id.to_le_bytes());
                    append_fixed_ascii_token8(&mut payload, tag);
                }
            }
        }
        payload
    }

    fn compact_divisions_data_payload(
        rows: &[DivisionMovementSample],
        elapsed_wall_ms: u64,
        status_flags: u32,
        changed_rows: u32,
        root_rows: u32,
    ) -> Vec<u8> {
        let mut payload = Vec::with_capacity(32usize.saturating_add(rows.len().saturating_mul(88)));
        payload.extend_from_slice(&elapsed_wall_ms.to_le_bytes());
        payload.extend_from_slice(&(rows.len().min(u32::MAX as usize) as u32).to_le_bytes());
        payload.extend_from_slice(&changed_rows.to_le_bytes());
        payload.extend_from_slice(&status_flags.to_le_bytes());
        payload.extend_from_slice(&COMPACT_FIXED_SCALE_RAW.to_le_bytes());
        payload.extend_from_slice(&root_rows.to_le_bytes());
        payload.extend_from_slice(&0u32.to_le_bytes());
        for sample in rows {
            let mut flags = 0u32;
            if sample.deleted {
                flags |= COMPACT_DIVISION_ROW_FLAG_DELETED;
            } else {
                if sample.moving {
                    flags |= 1;
                }
                if sample.raw_movement_progress.is_some() {
                    flags |= 1 << 1;
                }
                if sample.move_target_province.is_some() {
                    flags |= 1 << 2;
                }
                if sample.movement_source_province.is_some() {
                    flags |= 1 << 3;
                }
                if sample.in_combat {
                    flags |= 1 << 4;
                }
                if sample.owner_tag_db_id.is_some() {
                    flags |= 1 << 5;
                }
                if sample.army_id.is_some() {
                    flags |= 1 << 6;
                }
                if sample.raw_experience.is_some() {
                    flags |= 1 << 7;
                }
                if sample.raw_max_supply.is_some() {
                    flags |= 1 << 8;
                }
                if sample.raw_current_supply.is_some() {
                    flags |= 1 << 9;
                }
                if sample.raw_supply_gain.is_some() {
                    flags |= 1 << 10;
                }
                if sample.raw_fuel.is_some() {
                    flags |= 1 << 11;
                }
                if sample.template_id.is_some() {
                    flags |= COMPACT_DIVISION_ROW_FLAG_TEMPLATE;
                }
            }
            payload.extend_from_slice(&sample.div_id.to_le_bytes());
            payload.extend_from_slice(&DIVISION_TYPE.to_le_bytes());
            payload.extend_from_slice(&flags.to_le_bytes());
            payload.extend_from_slice(&sample.location.to_le_bytes());
            payload.extend_from_slice(&sample.move_target_province.unwrap_or(0).to_le_bytes());
            payload.extend_from_slice(&sample.movement_source_province.unwrap_or(0).to_le_bytes());
            payload.extend_from_slice(&sample.raw_movement_progress.unwrap_or(0).to_le_bytes());
            payload.extend_from_slice(&sample.progress_bucket.unwrap_or(0).to_le_bytes());
            payload.extend_from_slice(&sample.raw_organisation.to_le_bytes());
            payload.extend_from_slice(&sample.organisation_bucket.to_le_bytes());
            payload.extend_from_slice(&sample.raw_strength.to_le_bytes());
            payload.extend_from_slice(&sample.strength_bucket.to_le_bytes());
            payload.extend_from_slice(&sample.combat_ref_count.to_le_bytes());
            payload.extend_from_slice(&sample.template_id.unwrap_or(0).to_le_bytes());
            payload.extend_from_slice(&sample.owner_tag_db_id.unwrap_or(0).to_le_bytes());
            payload.extend_from_slice(&sample.army_id.unwrap_or(0).to_le_bytes());
            payload.extend_from_slice(&sample.raw_experience.unwrap_or(0).to_le_bytes());
            payload.extend_from_slice(&sample.raw_max_supply.unwrap_or(0).to_le_bytes());
            payload.extend_from_slice(&sample.raw_current_supply.unwrap_or(0).to_le_bytes());
            payload.extend_from_slice(&sample.raw_supply_gain.unwrap_or(0).to_le_bytes());
            payload.extend_from_slice(&sample.raw_fuel.unwrap_or(0).to_le_bytes());
            payload.extend_from_slice(&0u32.to_le_bytes());
        }
        payload
    }

    fn compact_division_equipment_data_payload(
        rows: &[DivisionEquipmentSample],
        elapsed_wall_ms: u64,
        status_flags: u32,
        changed_rows: u32,
        root_rows: u32,
        observed_division_rows: u32,
        observed_equipment_rows: u32,
    ) -> Vec<u8> {
        let equipment_entry_count = compact_division_equipment_entry_count(rows);
        let mut payload = Vec::with_capacity(
            40usize
                .saturating_add(rows.len().saturating_mul(24))
                .saturating_add(equipment_entry_count.saturating_mul(16)),
        );
        payload.extend_from_slice(&elapsed_wall_ms.to_le_bytes());
        payload.extend_from_slice(&(rows.len().min(u32::MAX as usize) as u32).to_le_bytes());
        payload.extend_from_slice(&changed_rows.to_le_bytes());
        payload.extend_from_slice(&status_flags.to_le_bytes());
        payload.extend_from_slice(&COMPACT_FIXED_SCALE_RAW.to_le_bytes());
        payload.extend_from_slice(&root_rows.to_le_bytes());
        payload.extend_from_slice(&observed_division_rows.to_le_bytes());
        payload.extend_from_slice(
            &(equipment_entry_count.min(u32::MAX as usize) as u32).to_le_bytes(),
        );
        payload.extend_from_slice(&observed_equipment_rows.to_le_bytes());

        let mut entry_cursor = 0u32;
        for sample in rows {
            let entry_count = sample.entries.len().min(u32::MAX as usize) as u32;
            let mut flags = 0u32;
            if sample.template_id.is_some() {
                flags |= COMPACT_DIVISION_EQUIPMENT_ROW_FLAG_TEMPLATE;
            }
            if sample.deleted {
                flags |= COMPACT_DIVISION_EQUIPMENT_ROW_FLAG_DELETED;
            }
            payload.extend_from_slice(&sample.owner_tag_db_id.to_le_bytes());
            payload.extend_from_slice(&sample.div_id.to_le_bytes());
            payload.extend_from_slice(&flags.to_le_bytes());
            payload.extend_from_slice(&sample.template_id.unwrap_or(0).to_le_bytes());
            payload.extend_from_slice(&entry_cursor.to_le_bytes());
            payload.extend_from_slice(&entry_count.to_le_bytes());
            entry_cursor = entry_cursor.saturating_add(entry_count);
        }
        for sample in rows {
            for entry in &sample.entries {
                payload.extend_from_slice(&entry.variant_id.to_le_bytes());
                payload.extend_from_slice(&0u32.to_le_bytes());
                payload.extend_from_slice(&entry.amount_raw.to_le_bytes());
            }
        }
        payload
    }

    fn compact_army_orders_data_payload(
        rows: &[CompactArmyOrderRow],
        elapsed_wall_ms: u64,
        status_flags: u32,
        changed_rows: u32,
        root_rows: u32,
        observed_army_rows: u32,
        observed_order_rows: u32,
        deleted_rows: u32,
    ) -> Vec<u8> {
        let target_state_count = compact_army_order_target_state_count(rows);
        let mut payload = Vec::with_capacity(
            40usize
                .saturating_add(rows.len().saturating_mul(48))
                .saturating_add(target_state_count.saturating_mul(8)),
        );
        payload.extend_from_slice(&elapsed_wall_ms.to_le_bytes());
        payload.extend_from_slice(&(rows.len().min(u32::MAX as usize) as u32).to_le_bytes());
        payload.extend_from_slice(&changed_rows.to_le_bytes());
        payload.extend_from_slice(&status_flags.to_le_bytes());
        payload.extend_from_slice(&root_rows.to_le_bytes());
        payload.extend_from_slice(&observed_army_rows.to_le_bytes());
        payload.extend_from_slice(&observed_order_rows.to_le_bytes());
        payload
            .extend_from_slice(&(target_state_count.min(u32::MAX as usize) as u32).to_le_bytes());
        payload.extend_from_slice(&deleted_rows.to_le_bytes());

        let mut target_cursor = 0u32;
        for row in rows {
            let target_count = row
                .target_states
                .as_ref()
                .map(Vec::len)
                .unwrap_or(0)
                .min(u32::MAX as usize) as u32;
            let mut flags = 0u32;
            if row.deleted {
                flags |= COMPACT_ARMY_ORDER_ROW_FLAG_DELETED;
            }
            if row.target_states.is_some() {
                flags |= COMPACT_ARMY_ORDER_ROW_FLAG_TARGET_STATES;
            }
            if row.target_state_count.is_some() {
                flags |= COMPACT_ARMY_ORDER_ROW_FLAG_TARGET_STATE_COUNT;
            }
            let target_first = if target_count == 0 { 0 } else { target_cursor };
            payload.extend_from_slice(&row.army_id.to_le_bytes());
            payload.extend_from_slice(&row.generation.to_le_bytes());
            payload.extend_from_slice(&flags.to_le_bytes());
            payload.extend_from_slice(&row.slot_index.to_le_bytes());
            payload.extend_from_slice(&row.order_type.to_le_bytes());
            payload.extend_from_slice(&target_first.to_le_bytes());
            payload.extend_from_slice(&target_count.to_le_bytes());
            payload.extend_from_slice(&row.target_state_count.unwrap_or(0).to_le_bytes());
            payload.extend_from_slice(
                &compact_army_order_target_status_code(row.target_status).to_le_bytes(),
            );
            payload.extend_from_slice(&0u32.to_le_bytes());
            payload.extend_from_slice(&0u32.to_le_bytes());
            target_cursor = target_cursor.saturating_add(target_count);
        }
        for row in rows {
            if let Some(states) = row.target_states.as_ref() {
                for state_id in states {
                    payload.extend_from_slice(&state_id.to_le_bytes());
                    payload.extend_from_slice(&0u32.to_le_bytes());
                }
            }
        }
        payload
    }

    fn compact_land_combats_data_payload(
        rows: &[LandCombatSample],
        elapsed_wall_ms: u64,
        status_flags: u32,
        changed_rows: u32,
        participant_count: u32,
        ended_count: u32,
    ) -> Vec<u8> {
        let mut payload = Vec::with_capacity(
            32usize
                .saturating_add(rows.len().saturating_mul(40))
                .saturating_add((participant_count as usize).saturating_mul(24)),
        );
        payload.extend_from_slice(&elapsed_wall_ms.to_le_bytes());
        payload.extend_from_slice(&(rows.len().min(u32::MAX as usize) as u32).to_le_bytes());
        payload.extend_from_slice(&changed_rows.to_le_bytes());
        payload.extend_from_slice(&status_flags.to_le_bytes());
        payload.extend_from_slice(&participant_count.to_le_bytes());
        payload.extend_from_slice(&ended_count.to_le_bytes());
        payload.extend_from_slice(&0u32.to_le_bytes());
        for sample in rows {
            let mut flags = 0u32;
            if sample.location.is_some() {
                flags |= 1;
            }
            if sample.day.is_some() {
                flags |= 1 << 1;
            }
            if sample.duration.is_some() {
                flags |= 1 << 2;
            }
            if sample.attacker_divisions.is_some() {
                flags |= 1 << 3;
            }
            if sample.defender_divisions.is_some() {
                flags |= 1 << 4;
            }
            payload.extend_from_slice(&sample.combat_id.to_le_bytes());
            payload.extend_from_slice(&sample.generation.to_le_bytes());
            payload.extend_from_slice(&flags.to_le_bytes());
            payload.extend_from_slice(&sample.location.unwrap_or(0).to_le_bytes());
            payload.extend_from_slice(&sample.day.unwrap_or(0).to_le_bytes());
            payload.extend_from_slice(&sample.duration.unwrap_or(0).to_le_bytes());
            payload.extend_from_slice(
                &(sample
                    .attacker_divisions
                    .as_ref()
                    .map(Vec::len)
                    .unwrap_or(0)
                    .min(u32::MAX as usize) as u32)
                    .to_le_bytes(),
            );
            payload.extend_from_slice(
                &(sample
                    .defender_divisions
                    .as_ref()
                    .map(Vec::len)
                    .unwrap_or(0)
                    .min(u32::MAX as usize) as u32)
                    .to_le_bytes(),
            );
            payload.extend_from_slice(&0u32.to_le_bytes());
        }
        for sample in rows {
            append_compact_land_combat_participants(&mut payload, sample, 1);
            append_compact_land_combat_participants(&mut payload, sample, 2);
        }
        payload
    }

    fn compact_map_control_data_payload(
        state_rows: &[CompactMapStateRow],
        province_rows: &[CompactMapProvinceRow],
        elapsed_wall_ms: u64,
        status_flags: u32,
        changed_rows: u32,
        changed_state_rows: u32,
        changed_province_rows: u32,
    ) -> Vec<u8> {
        let mut payload = Vec::with_capacity(
            32usize
                .saturating_add(state_rows.len().saturating_mul(16))
                .saturating_add(province_rows.len().saturating_mul(16)),
        );
        payload.extend_from_slice(&elapsed_wall_ms.to_le_bytes());
        payload.extend_from_slice(&(state_rows.len().min(u32::MAX as usize) as u32).to_le_bytes());
        payload.extend_from_slice(&changed_rows.to_le_bytes());
        payload.extend_from_slice(&status_flags.to_le_bytes());
        payload
            .extend_from_slice(&(province_rows.len().min(u32::MAX as usize) as u32).to_le_bytes());
        payload.extend_from_slice(&changed_state_rows.to_le_bytes());
        payload.extend_from_slice(&changed_province_rows.to_le_bytes());
        for row in state_rows {
            let mut flags = 0u32;
            if row.owner_tag_db_id != 0 {
                flags |= 1;
            }
            if row.controller_tag_db_id != 0 {
                flags |= 1 << 1;
            }
            payload.extend_from_slice(&row.state_id.to_le_bytes());
            payload.extend_from_slice(&row.owner_tag_db_id.to_le_bytes());
            payload.extend_from_slice(&row.controller_tag_db_id.to_le_bytes());
            payload.extend_from_slice(&flags.to_le_bytes());
        }
        for row in province_rows {
            let mut flags = 0u32;
            if row.controller_tag_db_id != 0 {
                flags |= 1;
            }
            if row.state_id != 0 {
                flags |= 1 << 1;
            }
            payload.extend_from_slice(&row.province_id.to_le_bytes());
            payload.extend_from_slice(&row.controller_tag_db_id.to_le_bytes());
            payload.extend_from_slice(&row.state_id.to_le_bytes());
            payload.extend_from_slice(&flags.to_le_bytes());
        }
        payload
    }

    fn compact_map_detail_data_payload(
        state_rows: &[CompactMapDetailStateRow],
        province_rows: &[CompactMapDetailProvinceRow],
        elapsed_wall_ms: u64,
        status_flags: u32,
        changed_rows: u32,
        observed_state_rows: u32,
        observed_province_rows: u32,
    ) -> Vec<u8> {
        let resource_count = state_rows
            .iter()
            .map(|row| row.resources.as_ref().map(Vec::len).unwrap_or(0))
            .sum::<usize>();
        let state_building_count = state_rows
            .iter()
            .map(|row| row.buildings.as_ref().map(Vec::len).unwrap_or(0))
            .sum::<usize>();
        let province_building_count = province_rows
            .iter()
            .map(|row| row.buildings.as_ref().map(Vec::len).unwrap_or(0))
            .sum::<usize>();
        let mut payload = Vec::with_capacity(
            48usize
                .saturating_add(state_rows.len().saturating_mul(28))
                .saturating_add(province_rows.len().saturating_mul(20))
                .saturating_add(resource_count.saturating_mul(12))
                .saturating_add(state_building_count.saturating_mul(12))
                .saturating_add(province_building_count.saturating_mul(12)),
        );
        payload.extend_from_slice(&elapsed_wall_ms.to_le_bytes());
        payload.extend_from_slice(&(state_rows.len().min(u32::MAX as usize) as u32).to_le_bytes());
        payload.extend_from_slice(&changed_rows.to_le_bytes());
        payload.extend_from_slice(&status_flags.to_le_bytes());
        payload
            .extend_from_slice(&(province_rows.len().min(u32::MAX as usize) as u32).to_le_bytes());
        payload.extend_from_slice(&observed_state_rows.to_le_bytes());
        payload.extend_from_slice(&observed_province_rows.to_le_bytes());
        payload.extend_from_slice(&(resource_count.min(u32::MAX as usize) as u32).to_le_bytes());
        payload
            .extend_from_slice(&(state_building_count.min(u32::MAX as usize) as u32).to_le_bytes());
        payload.extend_from_slice(
            &(province_building_count.min(u32::MAX as usize) as u32).to_le_bytes(),
        );
        payload.extend_from_slice(&0u32.to_le_bytes());

        let mut resource_cursor = 0u32;
        let mut state_building_cursor = 0u32;
        for row in state_rows {
            let resource_len = row
                .resources
                .as_ref()
                .map(Vec::len)
                .unwrap_or(0)
                .min(u32::MAX as usize) as u32;
            let building_len = row
                .buildings
                .as_ref()
                .map(Vec::len)
                .unwrap_or(0)
                .min(u32::MAX as usize) as u32;
            let mut flags = 0u32;
            if row.resources.is_some() {
                flags |= 1;
            }
            if row.buildings.is_some() {
                flags |= 1 << 1;
            }
            payload.extend_from_slice(&row.state_id.to_le_bytes());
            payload.extend_from_slice(&flags.to_le_bytes());
            payload.extend_from_slice(&resource_cursor.to_le_bytes());
            payload.extend_from_slice(&resource_len.to_le_bytes());
            payload.extend_from_slice(&state_building_cursor.to_le_bytes());
            payload.extend_from_slice(&building_len.to_le_bytes());
            payload.extend_from_slice(&0u32.to_le_bytes());
            resource_cursor = resource_cursor.saturating_add(resource_len);
            state_building_cursor = state_building_cursor.saturating_add(building_len);
        }

        let mut province_building_cursor = 0u32;
        for row in province_rows {
            let building_len = row
                .buildings
                .as_ref()
                .map(Vec::len)
                .unwrap_or(0)
                .min(u32::MAX as usize) as u32;
            let mut flags = 0u32;
            if row.state_id != 0 {
                flags |= 1;
            }
            if row.buildings.is_some() {
                flags |= 1 << 1;
            }
            payload.extend_from_slice(&row.province_id.to_le_bytes());
            payload.extend_from_slice(&row.state_id.to_le_bytes());
            payload.extend_from_slice(&flags.to_le_bytes());
            payload.extend_from_slice(&province_building_cursor.to_le_bytes());
            payload.extend_from_slice(&building_len.to_le_bytes());
            province_building_cursor = province_building_cursor.saturating_add(building_len);
        }

        for row in state_rows {
            if let Some(resources) = &row.resources {
                for resource in resources {
                    payload.extend_from_slice(&resource.resource_id.to_le_bytes());
                    payload.extend_from_slice(&resource.amount_raw.to_le_bytes());
                    payload.extend_from_slice(&0u32.to_le_bytes());
                }
            }
        }
        for row in state_rows {
            if let Some(buildings) = &row.buildings {
                append_compact_building_level_entries(&mut payload, buildings);
            }
        }
        for row in province_rows {
            if let Some(buildings) = &row.buildings {
                append_compact_building_level_entries(&mut payload, buildings);
            }
        }
        payload
    }

    fn compact_weather_data_payload(
        rows: &[CompactWeatherRegionRow],
        elapsed_wall_ms: u64,
        status_flags: u32,
        changed_rows: u32,
        observed_rows: u32,
    ) -> Vec<u8> {
        let active_region_count = rows.iter().filter(|row| row.phenomenon >= 1).count();
        let mut payload = Vec::with_capacity(48usize.saturating_add(rows.len().saturating_mul(32)));
        payload.extend_from_slice(&elapsed_wall_ms.to_le_bytes());
        payload.extend_from_slice(&(rows.len().min(u32::MAX as usize) as u32).to_le_bytes());
        payload.extend_from_slice(&changed_rows.to_le_bytes());
        payload.extend_from_slice(&status_flags.to_le_bytes());
        payload.extend_from_slice(&0u32.to_le_bytes());
        payload.extend_from_slice(&observed_rows.to_le_bytes());
        payload.extend_from_slice(&0u32.to_le_bytes());
        payload.extend_from_slice(&COMPACT_FIXED_SCALE_RAW.to_le_bytes());
        payload
            .extend_from_slice(&(active_region_count.min(u32::MAX as usize) as u32).to_le_bytes());
        payload.extend_from_slice(&0u32.to_le_bytes());
        payload.extend_from_slice(&0u32.to_le_bytes());
        for row in rows {
            payload.extend_from_slice(&row.region_id.to_le_bytes());
            payload.extend_from_slice(&row.flags.to_le_bytes());
            payload.extend_from_slice(&row.temperature_raw.to_le_bytes());
            payload.extend_from_slice(&row.phenomenon.to_le_bytes());
            payload.extend_from_slice(&row.next_weather_change_raw.to_le_bytes());
            payload.extend_from_slice(&row.active_modifier_count.to_le_bytes());
            payload.extend_from_slice(&row.intensity.to_le_bytes());
            payload.extend_from_slice(&0u32.to_le_bytes());
        }
        payload
    }

    fn append_compact_building_level_entries(
        payload: &mut Vec<u8>,
        buildings: &[CompactBuildingLevelEntry],
    ) {
        for building in buildings {
            payload.extend_from_slice(&building.type_id.to_le_bytes());
            payload.extend_from_slice(&building.level.to_le_bytes());
            payload.extend_from_slice(&0u32.to_le_bytes());
        }
    }

    fn append_compact_land_combat_participants(
        payload: &mut Vec<u8>,
        sample: &LandCombatSample,
        side: u32,
    ) {
        let divisions = if side == 1 {
            sample.attacker_divisions.as_ref()
        } else {
            sample.defender_divisions.as_ref()
        };
        if let Some(divisions) = divisions {
            for division_id in divisions {
                payload.extend_from_slice(&sample.combat_id.to_le_bytes());
                payload.extend_from_slice(&sample.generation.to_le_bytes());
                payload.extend_from_slice(&side.to_le_bytes());
                payload.extend_from_slice(&division_id.to_le_bytes());
                payload.extend_from_slice(&0u32.to_le_bytes());
            }
        }
    }

    fn append_fixed_ascii_token8(out: &mut Vec<u8>, token: &str) {
        let bytes = token.as_bytes();
        let len = bytes.len().min(8);
        out.extend_from_slice(&(len as u32).to_le_bytes());
        let mut fixed = [0u8; 8];
        fixed[..len].copy_from_slice(&bytes[..len]);
        out.extend_from_slice(&fixed);
    }

    fn append_compact_string(out: &mut Vec<u8>, value: Option<&str>) {
        let bytes = value.unwrap_or("").as_bytes();
        let len = bytes.len().min(u16::MAX as usize);
        out.extend_from_slice(&(len as u16).to_le_bytes());
        out.extend_from_slice(&bytes[..len]);
    }

    fn compact_scaled_i32(value: f64, scale: f64) -> Option<i32> {
        if !value.is_finite() {
            return None;
        }
        let scaled = (value * scale).round();
        if scaled < i32::MIN as f64 || scaled > i32::MAX as f64 {
            None
        } else {
            Some(scaled as i32)
        }
    }

    fn compact_scaled_i64(value: f64, scale: f64) -> Option<i64> {
        if !value.is_finite() {
            return None;
        }
        let scaled = (value * scale).round();
        if scaled < i64::MIN as f64 || scaled > i64::MAX as f64 {
            None
        } else {
            Some(scaled as i64)
        }
    }

    fn append_compact_frame_end_record(
        out: &mut Vec<u8>,
        sequence: u64,
        game_hour_raw: i32,
        elapsed_wall_ms: u64,
        frame_time_us: u64,
        emitted_domains: u32,
        scheduled_domain_count: u32,
        status_flags: u32,
    ) {
        let mut payload = Vec::with_capacity(32);
        payload.extend_from_slice(&elapsed_wall_ms.to_le_bytes());
        payload.extend_from_slice(&frame_time_us.to_le_bytes());
        payload.extend_from_slice(&emitted_domains.to_le_bytes());
        payload.extend_from_slice(&scheduled_domain_count.to_le_bytes());
        payload.extend_from_slice(&status_flags.to_le_bytes());
        payload.extend_from_slice(&0u32.to_le_bytes());
        append_compact_record(
            out,
            sequence,
            game_hour_raw,
            COMPACT_DOMAIN_FRAME,
            COMPACT_RECORD_TYPE_FRAME_END,
            0,
            &payload,
        );
    }

    fn append_compact_record(
        out: &mut Vec<u8>,
        sequence: u64,
        game_hour_raw: i32,
        domain_id: u16,
        record_type: u16,
        flags: u32,
        payload: &[u8],
    ) {
        out.extend_from_slice(COMPACT_RECORD_MAGIC);
        out.extend_from_slice(&COMPACT_RECORD_VERSION.to_le_bytes());
        out.extend_from_slice(&COMPACT_RECORD_HEADER_LEN.to_le_bytes());
        out.extend_from_slice(&sequence.to_le_bytes());
        out.extend_from_slice(&game_hour_raw.to_le_bytes());
        out.extend_from_slice(&domain_id.to_le_bytes());
        out.extend_from_slice(&record_type.to_le_bytes());
        out.extend_from_slice(&(payload.len().min(u32::MAX as usize) as u32).to_le_bytes());
        out.extend_from_slice(&flags.to_le_bytes());
        out.extend_from_slice(payload);
    }

    struct CollectorState {
        base: usize,
        daily_addr: usize,
        long_string_addr: usize,
        daily_match: bool,
        long_string_match: bool,
        date_ptr: u64,
        country_database_ptr: u64,
        country_identity: CountryIdentityCache,
        special_projects: SpecialProjectsCache,
        weather: CompactWeatherRoot,
    }

    impl CollectorState {
        fn resolve(control: Option<&CollectorControl>) -> CollectorState {
            let base = unsafe { GetModuleHandleW(ptr::null()) as usize };
            let daily_addr = base.saturating_add(C_GAME_STATE_DAILY_UPDATE_OFFSET);
            let long_string_addr = base.saturating_add(GET_LONG_STRING_OFFSET);
            let daily_match = base != 0 && sentinel_matches(daily_addr, &DAILY_UPDATE_SENTINEL);
            let long_string_match =
                base != 0 && sentinel_matches(long_string_addr, &GET_LONG_STRING_SENTINEL);
            let date_ptr = if daily_match && long_string_match {
                read_u64(base + CG_STATE_DATE_OFFSET).unwrap_or(0)
            } else {
                0
            };
            let country_database_ptr = if daily_match && long_string_match {
                read_u64(base + COUNTRY_DATABASE_OFFSET).unwrap_or(0)
            } else {
                0
            };
            let weather = if daily_match
                && long_string_match
                && control
                    .map(|control| compact_weather_enabled(control))
                    .unwrap_or(false)
            {
                resolve_compact_weather_root(base, date_ptr as usize).unwrap_or_default()
            } else {
                CompactWeatherRoot::default()
            };
            let skip_country_identity = control
                .map(|control| !lightweight_root_needs_country_identity(control))
                .unwrap_or(false);
            let country_identity = if daily_match && long_string_match && skip_country_identity {
                CountryIdentityCache::not_attempted("lightweight_root_frame")
            } else if daily_match
                && long_string_match
                && control
                    .map(|control| {
                        !control.country_object_bridge_valid || !control.country_record_bridge_valid
                    })
                    .unwrap_or(false)
            {
                CountryIdentityCache::not_attempted("invalid_control_bridge")
            } else if daily_match
                && long_string_match
                && control
                    .map(|control| !control.country_object_bridge.is_empty())
                    .unwrap_or(false)
            {
                let bridge = control
                    .map(|control| control.country_object_bridge.as_slice())
                    .unwrap_or(&[]);
                let record_bridge = control
                    .map(|control| control.country_record_bridge.as_slice())
                    .unwrap_or(&[]);
                CountryIdentityCache::from_control_bridge(
                    base,
                    country_database_ptr as usize,
                    bridge,
                    record_bridge,
                )
            } else if daily_match
                && long_string_match
                && control
                    .map(|control| control.country_object_scan)
                    .unwrap_or(false)
            {
                CountryIdentityCache::resolve(base, country_database_ptr as usize)
            } else if daily_match && long_string_match {
                let gamestate_rows = CountryIdentityCache::from_gamestate_country_table(
                    base,
                    date_ptr as usize,
                    country_database_ptr as usize,
                );
                if gamestate_rows.has_scalar_source() {
                    gamestate_rows
                } else {
                    let database_rows = CountryIdentityCache::from_country_database_root(
                        base,
                        country_database_ptr as usize,
                    );
                    if database_rows.has_scalar_source() {
                        database_rows
                    } else {
                        gamestate_rows
                    }
                }
            } else {
                CountryIdentityCache::not_attempted("profile_mismatch")
            };
            CollectorState {
                base,
                daily_addr,
                long_string_addr,
                daily_match,
                long_string_match,
                date_ptr,
                country_database_ptr,
                country_identity,
                special_projects: if daily_match
                    && long_string_match
                    && control
                        .map(|control| !control.special_projects_bridge_valid)
                        .unwrap_or(false)
                {
                    SpecialProjectsCache::not_attempted("invalid_control_bridge")
                } else if daily_match
                    && long_string_match
                    && control
                        .map(|control| !control.special_projects_bridge.is_empty())
                        .unwrap_or(false)
                {
                    let bridge = control
                        .map(|control| control.special_projects_bridge.as_slice())
                        .unwrap_or(&[]);
                    SpecialProjectsCache::from_control_bridge(base, bridge)
                } else if daily_match
                    && long_string_match
                    && control
                        .map(|control| control.special_projects_scan)
                        .unwrap_or(false)
                {
                    SpecialProjectsCache::resolve(base)
                } else {
                    SpecialProjectsCache::not_attempted("disabled")
                },
                weather,
            }
        }
    }

