    fn domains_json_with_extra_domain(domains: String, domain: &str) -> String {
        let encoded = json_str(domain);
        if domains.contains(&encoded) {
            return domains;
        }
        if domains == "[]" {
            return format!("[{encoded}]");
        }
        let Some(prefix) = domains.strip_suffix(']') else {
            return domains;
        };
        format!("{prefix},{encoded}]")
    }

    fn root_probe_json(
        state: Option<&CollectorState>,
        scheduled_state_rows: Option<&str>,
        scheduled_province_rows: Option<&str>,
        scheduled_special_projects: Option<&str>,
        include_country_rows: bool,
        compact_country_frame: bool,
        include_scheduled_country_fuel: bool,
        include_scheduled_country_production: bool,
        include_scheduled_country_focus: bool,
        include_scheduled_country_research: bool,
        include_scheduled_country_politics: bool,
        include_scheduled_country_politics_residuals: bool,
        include_scheduled_country_decisions: bool,
        include_scheduled_country_diplomacy: bool,
        control: Option<&CollectorControl>,
        advisor_token_filter: Option<&BTreeMap<String, AdvisorTokenInfo>>,
        tech_def_filter: Option<&BTreeMap<u32, String>>,
        idea_group_filter: Option<&BTreeMap<String, String>>,
        frame_clock: Option<&ClockSample>,
        mut compact_country_tracker: Option<&mut CompactCountryFrameTracker>,
    ) -> (String, String) {
        let Some(state) = state else {
            return ("\"root_probe\":null".to_string(), "[]".to_string());
        };
        let base = state.base;
        if state.base == 0 {
            return (
                "\"root_probe\":{\"status\":\"profile_mismatch\",\"reason\":\"no_image_base\"}"
                    .to_string(),
                "[]".to_string(),
            );
        }

        if !(state.daily_match && state.long_string_match) {
            return (
                format!(
                    "\"root_probe\":{{\"status\":\"profile_mismatch\",\
                     \"image_base\":\"0x{base:X}\",\
                     \"daily_update_sentinel_match\":{},\
                     \"long_string_sentinel_match\":{}}}",
                    state.daily_match, state.long_string_match
                ),
                "[]".to_string(),
            );
        }

        let date_ptr = state.date_ptr;
        let country_database_ptr = state.country_database_ptr;
        let country_probe = country_database_probe_json(country_database_ptr as usize);
        let mut current_rows = if include_country_rows {
            state.country_identity.current_rows(
                country_database_ptr as usize,
                compact_country_frame,
                include_scheduled_country_fuel,
                include_scheduled_country_production,
                include_scheduled_country_focus,
                include_scheduled_country_research,
                include_scheduled_country_politics,
                include_scheduled_country_politics_residuals,
                include_scheduled_country_decisions,
                include_scheduled_country_diplomacy,
                advisor_token_filter,
                tech_def_filter,
                idea_group_filter,
                if compact_country_frame {
                    compact_country_tracker.as_deref_mut()
                } else {
                    None
                },
            )
        } else {
            Vec::new()
        };
        let tag_table = country_tag_table(country_database_ptr as usize);
        let war_relations = if include_scheduled_country_diplomacy {
            match (control, tag_table) {
                (Some(control), Some(tag_table))
                    if control.war_relation_bridge_valid
                        && war_relation_bridge_well_formed(&control.war_relation_bridge) =>
                {
                    read_war_relation_rows(base as usize, tag_table, &control.war_relation_bridge)
                }
                _ => None,
            }
        } else {
            None
        };
        if let Some(war_relations) = war_relations.as_ref() {
            apply_war_relations_to_country_rows(&mut current_rows, war_relations);
        }
        let country_rows = if include_country_rows {
            state.country_identity.countries_json_from_rows(
                country_database_ptr as usize,
                &current_rows,
                compact_country_frame,
                include_scheduled_country_fuel,
                include_scheduled_country_production,
                include_scheduled_country_focus,
                include_scheduled_country_research,
                include_scheduled_country_politics,
                include_scheduled_country_politics_residuals,
                include_scheduled_country_decisions,
                include_scheduled_country_diplomacy,
                compact_country_tracker.as_deref_mut(),
            )
        } else {
            "{}".to_string()
        };
        let identity_probe = if include_country_rows {
            state.country_identity.root_json()
        } else {
            "\"country_object_identity\":{\"status\":\"lightweight_root_frame\",\
             \"scan_ms\":0,\"bridge_rows_supplied\":0,\
             \"record_rows_supplied\":0,\"object_count\":0,\
             \"rejected_objects\":0,\"duplicate_tags\":0}"
                .to_string()
        };
        let has_building_rows = scheduled_state_rows
            .map(|rows| rows.contains("\"buildings\":"))
            .unwrap_or(false)
            || scheduled_province_rows
                .map(|rows| rows.contains("\"buildings\":"))
                .unwrap_or(false);
        let has_state_resource_rows = scheduled_state_rows
            .map(|rows| rows.contains("\"resources\":"))
            .unwrap_or(false);
        let domains = if include_country_rows {
            state.country_identity.domains_json_from_rows(
                &current_rows,
                scheduled_state_rows.is_some(),
                scheduled_province_rows.is_some(),
                scheduled_special_projects.is_some(),
                compact_country_frame,
                include_scheduled_country_fuel,
                include_scheduled_country_production,
                include_scheduled_country_focus,
                include_scheduled_country_research,
                include_scheduled_country_politics,
                include_scheduled_country_politics_residuals,
                include_scheduled_country_decisions,
            )
        } else {
            let mut domains = "[\"clock\"]".to_string();
            if scheduled_state_rows.is_some() {
                domains = domains_json_with_extra_domain(domains, "state_ownership");
                domains = domains_json_with_extra_domain(domains, "state_control");
            }
            if scheduled_province_rows.is_some() {
                domains = domains_json_with_extra_domain(domains, "province_control");
            }
            if scheduled_special_projects.is_some() {
                domains = domains_json_with_extra_domain(domains, "projects_live");
            }
            domains
        };
        let domains = if has_building_rows {
            domains_json_with_extra_domain(domains, "buildings_live")
        } else {
            domains
        };
        let domains = if has_state_resource_rows {
            domains_json_with_extra_domain(domains, "state_detail")
        } else {
            domains
        };
        let domains = if include_scheduled_country_diplomacy
            && current_rows.iter().any(|row| row.diplomacy.is_some())
        {
            domains_json_with_extra_domain(domains, "diplomacy_live")
        } else {
            domains
        };
        let clock_probe = clock_probe_json(date_ptr as usize, frame_clock);
        let special_projects_probe = state.special_projects.root_json();
        let state_rows = scheduled_state_rows
            .map(|rows| format!(",\"states\":{rows}"))
            .unwrap_or_default();
        let province_rows = scheduled_province_rows
            .map(|rows| format!(",\"provinces\":{rows}"))
            .unwrap_or_default();
        let diplomacy_live = war_relations
            .as_ref()
            .and_then(|rows| diplomacy_live_sidecar_json(&current_rows, rows))
            .unwrap_or_default();
        (
            format!(
                "\"root_probe\":{{\"status\":\"verified\",\
                 \"profile\":\"{}\",\
                 \"image_base\":\"0x{base:X}\",\
                 \"daily_update\":\"0x{:X}\",\
                 \"get_long_string\":\"0x{:X}\",\
                 \"daily_update_sentinel_match\":true,\
                 \"long_string_sentinel_match\":true,\
                 \"date_root_ptr\":\"0x{date_ptr:X}\",\
                 \"country_database_root_ptr\":\"0x{country_database_ptr:X}\",\
                 {clock_probe},\
                 {country_probe},\
                 {identity_probe},\
                 {special_projects_probe},\
                 \"domains\":{domains}}},\
                 \"countries\":{country_rows}{diplomacy_live}{state_rows}{province_rows}",
                super::COLLECTOR_PROFILE_ID,
                state.daily_addr,
                state.long_string_addr
            ),
            domains,
        )
    }

    fn is_hoi4_process() -> bool {
        process_path()
            .and_then(|p| {
                p.file_name()
                    .map(|n| n.to_string_lossy().to_ascii_lowercase())
            })
            .as_deref()
            == Some("hoi4.exe")
    }

    fn sentinel_matches(addr: usize, sentinel: &[u8]) -> bool {
        read_bytes(addr, sentinel.len())
            .map(|bytes| bytes == sentinel)
            .unwrap_or(false)
    }

    fn read_u64(addr: usize) -> Option<u64> {
        let bytes = read_bytes(addr, 8)?;
        let mut arr = [0u8; 8];
        arr.copy_from_slice(&bytes);
        Some(u64::from_le_bytes(arr))
    }

    fn read_u32(addr: usize) -> Option<u32> {
        let bytes = read_bytes(addr, 4)?;
        let mut arr = [0u8; 4];
        arr.copy_from_slice(&bytes);
        Some(u32::from_le_bytes(arr))
    }

    fn read_u16(addr: usize) -> Option<u16> {
        let bytes = read_bytes(addr, 2)?;
        let mut arr = [0u8; 2];
        arr.copy_from_slice(&bytes);
        Some(u16::from_le_bytes(arr))
    }

    fn read_u8(addr: usize) -> Option<u8> {
        read_bytes(addr, 1).and_then(|bytes| bytes.first().copied())
    }

    fn country_database_probe_json(country_database_ptr: usize) -> String {
        if country_database_ptr == 0 {
            return "\"country_tag_count\":null,\"country_active_count\":null,\
                    \"tag_sample\":[]"
                .to_string();
        }
        let tag_table = read_u64(country_database_ptr).unwrap_or(0) as usize;
        let tag_count = read_u32(country_database_ptr + 8).unwrap_or(0);
        let active_count = read_u32(country_database_ptr + 12).unwrap_or(0);
        let sample = tag_sample_json(tag_table, tag_count.min(12));
        format!(
            "\"country_tag_count\":{tag_count},\
             \"country_active_count\":{active_count},\
             \"tag_sample\":{sample}"
        )
    }

    fn country_rows_from_tag_table_json(country_database_ptr: usize) -> String {
        if country_database_ptr == 0 {
            return "{}".to_string();
        }
        let tag_table = read_u64(country_database_ptr).unwrap_or(0) as usize;
        let tag_count = read_u32(country_database_ptr + 8).unwrap_or(0);
        let active_count = read_u32(country_database_ptr + 12).unwrap_or(0);
        if tag_table == 0 || tag_count == 0 || active_count == 0 {
            return "{}".to_string();
        }
        let row_count = tag_count.min(active_count).min(1024);
        let mut rows = Vec::new();
        for i in 0..row_count as usize {
            let Some(tag) = read_small_inline_string(tag_table + i * 32) else {
                continue;
            };
            if is_country_tag(&tag) {
                rows.push(format!(
                    "\"{tag}\":{{\"present\":true,\"identity\":{{\"tag_db_id\":{i}}}}}"
                ));
            }
        }
        format!("{{{}}}", rows.join(","))
    }

    fn country_tag_table(country_database_ptr: usize) -> Option<usize> {
        if country_database_ptr == 0 {
            return None;
        }
        let tag_table = read_u64(country_database_ptr)? as usize;
        let tag_count = read_u32(country_database_ptr + 8)?;
        if tag_table == 0 || tag_count < 40 || tag_count > 1024 {
            return None;
        }
        let prefix = ["---", "GER", "ENG", "SOV"];
        for (i, want) in prefix.iter().enumerate() {
            let got = read_small_inline_string(tag_table + i * 32)?;
            if got != *want {
                return None;
            }
        }
        Some(tag_table)
    }

    fn country_tag_row_count(country_database_ptr: usize) -> Option<u32> {
        if country_database_ptr == 0 {
            return None;
        }
        let tag_count = read_u32(country_database_ptr + 8)?;
        let active_count = read_u32(country_database_ptr + 12)?;
        if active_count == 0 || active_count > tag_count || tag_count > 1024 {
            return None;
        }
        let row_count = tag_count.min(active_count).min(1024);
        if row_count <= MIN_USABLE_COUNTRY_OBJECT_ROWS as u32 {
            return None;
        }
        Some(row_count)
    }

    fn country_object_array_base_candidates(field_addr: usize) -> Vec<usize> {
        let mut candidates = vec![field_addr];
        if let Some(ptr) = read_u64(field_addr).map(|value| value as usize) {
            if ptr > 0 && ptr % 8 == 0 && ptr != field_addr {
                candidates.push(ptr);
            }
        }
        candidates
    }

    fn country_rows_from_tag_indexed_array(
        array_base: usize,
        country_vtable: usize,
        tag_table: usize,
        tag_row_count: u32,
    ) -> Option<Vec<CountryObjectRow>> {
        if !is_map_control_heap_pointer(array_base)
            || tag_row_count <= MIN_USABLE_COUNTRY_OBJECT_ROWS as u32
            || tag_row_count > 1024
        {
            return None;
        }

        let mut rows = Vec::new();
        let mut seen_objects: BTreeMap<usize, ()> = BTreeMap::new();
        let mut holes = 0usize;
        for tag_db_id in 1..tag_row_count {
            let slot_addr = array_base.checked_add(tag_db_id as usize * 8)?;
            let object_ptr = read_u64(slot_addr).unwrap_or(0) as usize;
            if object_ptr == 0 {
                holes += 1;
                if holes >= 16 && tag_db_id as usize > MIN_USABLE_COUNTRY_OBJECT_ROWS {
                    break;
                }
                continue;
            }
            holes = 0;
            if !is_map_control_heap_pointer(object_ptr)
                || seen_objects.insert(object_ptr, ()).is_some()
            {
                return None;
            }
            let row = country_object_row_expected(
                object_ptr,
                country_vtable,
                tag_table,
                tag_db_id,
                None,
                false,
                false,
                false,
                false,
                false,
                false,
                false,
                false,
                false,
                None,
                None,
                None,
            )?;
            rows.push(row);
        }

        if rows.len() >= MIN_USABLE_COUNTRY_OBJECT_ROWS {
            Some(rows)
        } else {
            None
        }
    }

    fn country_tag_object_map(rows: &[CountryObjectRow]) -> BTreeMap<u32, usize> {
        rows.iter()
            .map(|row| (row.tag_db_id, row.object_ptr))
            .collect()
    }

    fn country_tag_object_maps_agree(
        left: &BTreeMap<u32, usize>,
        right: &BTreeMap<u32, usize>,
    ) -> bool {
        let mut shared = 0usize;
        for (tag_db_id, object_ptr) in left {
            if let Some(other_object_ptr) = right.get(tag_db_id) {
                shared += 1;
                if object_ptr != other_object_ptr {
                    return false;
                }
            }
        }
        shared >= MIN_USABLE_COUNTRY_OBJECT_ROWS
    }

    fn tag_from_table(tag_table: usize, tag_db_id: u32) -> Option<String> {
        if tag_db_id > 1024 {
            return None;
        }
        read_small_inline_string(tag_table + tag_db_id as usize * 32)
            .filter(|tag| is_country_tag(tag))
    }

    fn country_object_row(
        object_ptr: usize,
        country_vtable: usize,
        tag_table: usize,
        record_ptr: Option<usize>,
        compact_country_frame: bool,
        include_scheduled_country_fuel: bool,
        include_scheduled_country_production: bool,
        include_scheduled_country_focus: bool,
        include_scheduled_country_research: bool,
        include_scheduled_country_politics: bool,
        include_scheduled_country_politics_residuals: bool,
        include_scheduled_country_decisions: bool,
        include_scheduled_country_diplomacy: bool,
        advisor_token_filter: Option<&BTreeMap<String, AdvisorTokenInfo>>,
        tech_def_filter: Option<&BTreeMap<u32, String>>,
        idea_group_filter: Option<&BTreeMap<String, String>>,
    ) -> Option<CountryObjectRow> {
        if read_u64(object_ptr)? as usize != country_vtable {
            return None;
        }
        let name = read_msvc_string(object_ptr + OBJ_NAME, 96)?;
        if read_msvc_string(object_ptr + OBJ_NAME, 96)? != name {
            return None;
        }
        let tag_db_id = read_u32(object_ptr + OBJ_TAG_DB_ID)?;
        let tag = tag_from_table(tag_table, tag_db_id)?;
        let original_tag_id = read_u16(object_ptr + OBJ_ORIGINAL_TAG);
        let original_tag = original_tag_id.and_then(|id| {
            if id == 0 {
                None
            } else {
                tag_from_table(tag_table, id as u32)
            }
        });
        let (politics, politics_residuals) = match (
            include_scheduled_country_politics,
            include_scheduled_country_politics_residuals,
        ) {
            (true, true) => read_country_politics_bundle(
                object_ptr,
                country_vtable,
                idea_group_filter,
                advisor_token_filter,
                compact_country_frame,
            ),
            (true, false) => (
                read_country_politics(
                    object_ptr,
                    country_vtable,
                    idea_group_filter,
                    compact_country_frame,
                ),
                None,
            ),
            (false, true) => (
                None,
                read_country_politics_residuals(
                    object_ptr,
                    country_vtable,
                    advisor_token_filter,
                    compact_country_frame,
                ),
            ),
            (false, false) => (None, None),
        };
        Some(CountryObjectRow {
            tag,
            tag_db_id,
            name,
            object_ptr,
            record_ptr,
            original_capital: if compact_country_frame {
                None
            } else {
                read_i32(object_ptr + OBJ_ORIGINAL_CAPITAL).and_then(|v| {
                    if v > 0 {
                        Some(v)
                    } else {
                        None
                    }
                })
            },
            original_tag: if compact_country_frame {
                None
            } else {
                original_tag
            },
            templates_locked: if compact_country_frame {
                None
            } else {
                read_u8(object_ptr + OBJ_TEMPLATES_LOCKED).map(|v| v == 1)
            },
            reserved_dynamic_country: if compact_country_frame {
                None
            } else {
                read_u8(object_ptr + OBJ_RESERVED_DYNAMIC_COUNTRY).map(|v| v == 1)
            },
            stability: if compact_country_frame {
                None
            } else {
                read_fixed_0_1(object_ptr + OBJ_STABILITY)
            },
            war_support: if compact_country_frame {
                None
            } else {
                read_fixed_0_1(object_ptr + OBJ_WAR_SUPPORT)
            },
            political_power: if compact_country_frame {
                None
            } else {
                country_object_political_power(object_ptr, country_vtable, record_ptr)
            },
            command_power: if compact_country_frame {
                None
            } else {
                read_fixed_nonnegative(object_ptr + OBJ_COMMAND_POWER, 1000.0)
            },
            num_ships: if compact_country_frame {
                None
            } else {
                read_i32(object_ptr + OBJ_NUM_SHIPS).and_then(|v| {
                    if (0..=100_000).contains(&v) {
                        Some(v)
                    } else {
                        None
                    }
                })
            },
            manpower_pool: if compact_country_frame {
                None
            } else {
                read_u32(object_ptr + OBJ_MANPOWER_POOL).and_then(|v| {
                    if v <= 2_000_000_000 {
                        Some(v)
                    } else {
                        None
                    }
                })
            },
            convoys: if compact_country_frame {
                None
            } else {
                read_fixed_nonnegative(object_ptr + OBJ_CONVOYS, 1_000_000.0)
            },
            misc: if compact_country_frame {
                None
            } else {
                read_country_misc(object_ptr)
            },
            fuel: if include_scheduled_country_fuel {
                read_country_fuel(object_ptr)
            } else {
                None
            },
            production: if include_scheduled_country_production {
                read_country_production(object_ptr, country_vtable)
            } else {
                None
            },
            focus: if include_scheduled_country_focus {
                read_country_focus(object_ptr, compact_country_frame)
            } else {
                None
            },
            research: if include_scheduled_country_research {
                read_country_research(
                    object_ptr,
                    country_vtable,
                    tech_def_filter,
                    compact_country_frame,
                )
            } else {
                None
            },
            politics,
            politics_residuals,
            decisions: if include_scheduled_country_decisions {
                read_country_decisions(object_ptr, country_vtable)
            } else {
                None
            },
            diplomacy: if include_scheduled_country_diplomacy {
                read_country_diplomacy(object_ptr)
            } else {
                None
            },
        })
    }

